#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */
async function main() {
    console.log('Starting database migration script...');

    // Define the migrations directory
    const migrationsDir = path.join(__dirname, 'migrations');

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${migrationsDir}`);
        console.log('Please create a ./migrations/ directory with SQL migration files.');
        process.exit(1);
    }

    // Read all files from migrations directory
    let migrationFiles;
    try {
        migrationFiles = fs.readdirSync(migrationsDir);
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }

    // Filter for .sql files
    const sqlFiles = migrationFiles.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in ./migrations/ directory.');
        return;
    }

    console.log(`Found ${sqlFiles.length} SQL migration file(s):`);

    // Sort files by name (assuming naming convention like 001_name.sql, 002_name.sql)
    const sortedFiles = sqlFiles.sort();

    // Log each file in order
    sortedFiles.forEach((file, index) => {
        const filePath = path.join(migrationsDir, file);
        console.log(`[${index + 1}/${sortedFiles.length}] ${file}`);

        // Optional: Read and display the first few lines of the SQL file
        try {
            const content = fs.readFileSync(filePath, 'utf8');
            const lines = content.split('\n');
            const firstLine = lines[0].trim();
            console.log(`  SQL: ${firstLine.substring(0, 60)}${firstLine.length > 60 ? '...' : ''}`);
        } catch (error) {
            console.log(`  Could not read file: ${error.message}`);
        }
    });

    console.log('\nMigration script completed.');
    console.log('Note: This script only logs the migration files.');
    console.log('To actually apply migrations, you would need to:');
    console.log('1. Connect to your database');
    console.log('2. Execute the SQL content of each file');
    console.log('3. Track which migrations have been applied');
}

// Handle command line arguments for future enhancement
const args = process.argv.slice(2);
const command = args[0] || 'list';

if (command === 'list' || command === '--list' || command === '-l') {
    main().catch(error => {
        console.error('Unexpected error:', error);
        process.exit(1);
    });
} else if (command === '--help' || command === '-h') {
    console.log(`
Database Migration Script

Usage:
  node migrate.js [command]

Commands:
  list, --list, -l    List migration files in order (default)
  --help, -h          Show this help message

Description:
  This script reads SQL files from ./migrations/ directory and logs each
  filename it would apply, in order. Files are sorted alphabetically by name.

Examples:
  node migrate.js              # List migration files
  node migrate.js --list       # List migration files
  node migrate.js --help       # Show help
    `);
} else {
    console.error(`Unknown command: ${command}`);
    console.log('Use --help for usage information.');
    process.exit(1);
}

// Test the migration script by temporarily renaming the migrations directory
const fs = require('fs');
const path = require('path');

const originalDir = path.join(__dirname, 'migrations');
const tempDir = path.join(__dirname, 'migrations_temp');

// Temporarily rename migrations directory
if (fs.existsSync(originalDir)) {
    fs.renameSync(originalDir, tempDir);
    console.log('Temporarily moved migrations directory to test error handling');
}

// Run migrate.js without migrations directory
console.log('\n=== Testing without migrations directory ===');
const { execSync } = require('child_process');
try {
    execSync('node migrate.js', { stdio: 'inherit' });
} catch (error) {
    console.log('Script exited with error as expected');
}

// Restore migrations directory
if (fs.existsSync(tempDir)) {
    fs.renameSync(tempDir, originalDir);
    console.log('\nRestored migrations directory');

    // Test with migrations directory
    console.log('\n=== Testing with migrations directory ===');
    execSync('node migrate.js', { stdio: 'inherit' });
}

// Clean up test file
fs.unlinkSync(path.join(__dirname, 'test_migrate.js'));

