function loadEnvFile() {
    const envFilePath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envFilePath)) {
        console.warn(`Warning: .env.test file not found at ${envFilePath}`);
        return {};
    }

    try {
        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const envVars = {};

        envContent.split('\n').forEach(line => {
            line = line.trim();
            // Skip empty lines and comments
            if (!line || line.startsWith('#')) {
                return;
            }

            // Parse KEY=VALUE pairs
            const equalsIndex = line.indexOf('=');
            if (equalsIndex !== -1) {
                const key = line.substring(0, equalsIndex).trim();
                const value = line.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        });

        return envVars;
    } catch (error) {
        console.warn(`Warning: Could not read .env.test file: ${error.message}`);
        return {};
    }
}

/**
 * Parse database URL to extract connection details
 * @param {string} databaseUrl - The DATABASE_URL string
 * @returns {Object} Parsed connection details or null if invalid
 */
function parseDatabaseUrl(databaseUrl) {
    if (!databaseUrl) {
        return null;
    }

    try {
        // Parse PostgreSQL URL format: postgres://username:password@host:port/database
        const url = new URL(databaseUrl);

        // Sanitize password for logging (show only first few characters)
        const password = url.password;
        const sanitizedPassword = password ? 
            (password.startsWith('CANARY-') ? password : `${password.substring(0, 3)}***`) : 
