#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Array of migration file paths sorted in order
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Migrations directory not found: ${this.migrationsDir}`);
                process.exit(1);
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            // Sort files by their numeric prefix
            sqlFiles.sort((a, b) => {
                // Extract numeric prefix from filename
                const getNumber = (filename) => {
                    const match = filename.match(/^(\d+)_/);
                    return match ? parseInt(match[1]) : 0;
                };
                return getNumber(a) - getNumber(b);
            });

            // Convert to full paths
            return sqlFiles.map(file => path.join(this.migrationsDir, file));
        } catch (error) {
            console.error('Error reading migrations directory:', error.message);
            process.exit(1);
        }
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('Database Migration Script');
        console.log('=========================');
        console.log(`Reading migrations from: ${this.migrationsDir}`);
        console.log();

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):`);
        console.log();

        // Log each migration file
        migrationFiles.forEach((filePath, index) => {
            const fileName = path.basename(filePath);
            const migrationNumber = index + 1;

            console.log(`${migrationNumber}. ${fileName}`);

            // Optional: Log a preview of the SQL content
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const lines = content.split('\n');
                const firstLine = lines[0].trim();
                console.log(`   ${firstLine.substring(0, 60)}${firstLine.length > 60 ? '...' : ''}`);
            } catch (error) {
                console.log(`   [Error reading file: ${error.message}]`);
            }

            console.log();
        });

        console.log('All migrations logged successfully.');
        console.log(`Total: ${migrationFiles.length} migration(s) would be applied.`);
    }

    /**
     * Run the migration script
     */
    run() {
        this.logMigrations();
    }
}

// Main execution
if (require.main === module) {
    const migrationRunner = new MigrationRunner();
    migrationRunner.run();
}

module.exports = MigrationRunner;

