#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Function to read DATABASE_URL from .env.test file
function readDatabaseUrl() {
    const envFilePath = path.join(__dirname, '.env.test');

    try {
        // Check if .env.test file exists
        if (!fs.existsSync(envFilePath)) {
            console.warn('Warning: .env.test file not found.');
            return null;
        }

        // Read the file
        const envContent = fs.readFileSync(envFilePath, 'utf8');

        // Parse DATABASE_URL from the file
        const lines = envContent.split('\n');
        for (const line of lines) {
            // Skip comments and empty lines
            const trimmedLine = line.trim();
            if (trimmedLine.startsWith('#') || trimmedLine.length === 0) {
                continue;
            }

            // Look for DATABASE_URL
            if (trimmedLine.startsWith('DATABASE_URL=')) {
                return trimmedLine.substring('DATABASE_URL='.length).trim();
            }
        }

        console.warn('Warning: DATABASE_URL not found in .env.test file.');
        return null;
    } catch (error) {
        console.warn(`Warning: Could not read .env.test file: ${error.message}`);
        return null;
    }
}

// Function to mask sensitive parts of the database URL for logging
function maskDatabaseUrl(url) {
    if (!url) return null;

    try {
        // Parse the URL to mask the password
        const urlParts = url.match(/^(postgres:\/\/)([^:]+):([^@]+)@(.+)$/);
        if (urlParts) {
            const [, protocol, username, password, rest] = urlParts;
            // Mask the password
            return `${protocol}${username}:*****@${rest}`;
        }
        return url; // Return as-is if we can't parse it
    } catch (error) {
        return url; // Return as-is if parsing fails
    }
}

// Main function that reads SQL files from ./migrations/ directory
// and logs each filename it would apply, in order
function runMigrationScript() {
    console.log('Starting migration script...');
    console.log('=============================\n');

    // Read DATABASE_URL from .env.test
    const databaseUrl = readDatabaseUrl();

    if (databaseUrl) {
        const maskedUrl = maskDatabaseUrl(databaseUrl);
        console.log(`✓ Connected to database: ${maskedUrl}`);
        console.log('  (Note: This is a simulation - no actual connection was made)\n');
    } else {
        console.log('⚠ No DATABASE_URL found. Running in dry-run mode.\n');
    }

    const migrationsDir = path.join(__dirname, 'migrations');

    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.error(`Error: Directory '${migrationsDir}' not found.`);
            process.exit(1);
        }

        // Read all files in the migrations directory
        const allFiles = fs.readdirSync(migrationsDir);

        // Filter for SQL files
        const sqlFiles = allFiles.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log('No SQL files found in migrations directory.');
            return;
        }

        // Sort files in order (by numeric prefix if available)
        sqlFiles.sort((a, b) => {
