#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Sorted array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory "${this.migrationsDir}" not found.`);
                process.exit(1);
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files (files ending with .sql)
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            if (sqlFiles.length === 0) {
                console.log(`No SQL migration files found in "${this.migrationsDir}".`);
                return [];
            }

            // Sort files alphabetically (which should sort numerically if using prefixes like 001_, 002_, etc.)
            const sortedFiles = sqlFiles.sort();

            // Create array of file objects with name and full path
            const migrationFiles = sortedFiles.map(file => ({
                name: file,
                path: path.join(this.migrationsDir, file)
            }));

            return migrationFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Read and log the migration files in order
     */
    logMigrations() {
        console.log('=== Database Migration Script ===');
        console.log(`Reading migration files from: ${this.migrationsDir}\n`);

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files to process.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration files:\n`);

        // Log each migration file in order
        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file.name}`);

            // Optionally read and show a preview of the SQL content
            try {
                const content = fs.readFileSync(file.path, 'utf8');
                const preview = content.split('\n')[0].trim();
                if (preview) {
                    console.log(`   Preview: ${preview}${preview.length > 50 ? '...' : ''}`);
                }
            } catch (error) {
                console.log(`   [Error reading file: ${error.message}]`);
            }
            console.log(); // Empty line for better readability
        });

        console.log('=== End of Migration List ===');
        console.log('\nNote: This script only logs the migration files that would be applied.');
        console.log('To actually execute these migrations, you would need to:');
        console.log('1. Read the SQL content from each file');
        console.log('2. Connect to your database');
        console.log('3. Execute each SQL statement in order');
        console.log('4. Track which migrations have been applied (using a migration table)');
    }

    /**
     * Main method to run the migration logging
     */
    run() {
        this.logMigrations();
    }
}

// Parse command line arguments
function parseArguments() {
    const args = process.argv.slice(2);
    const options = {
        migrationsDir: './migrations'
    };

    for (let i = 0; i < args.length; i++) {
        if (args[i] === '--dir' && i + 1 < args.length) {
            options.migrationsDir = args[i + 1];
            i++; // Skip next argument since we've used it
        } else if (args[i] === '--help' || args[i] === '-h') {
            showHelp();
            process.exit(0);
        } else if (args[i].startsWith('--dir=')) {
            options.migrationsDir = args[i].substring(6);
        }
    }

    return options;
}

function showHelp() {
    console.log(`
Database Migration Script

Usage: node migrate.js [options]

Options:
  --dir=<path>    Specify custom migrations directory (default: ./migrations)
  --help, -h      Show this help message

Example:
  node migrate.js                    # Use default ./migrations directory
  node migrate.js --dir=./db/changes # Use custom directory
  `);
}

// Main execution
if (require.main === module) {
    const options = parseArguments();
    const migrationRunner = new MigrationRunner(options.migrationsDir);
    migrationRunner.run();
}

module.exports = MigrationRunner;

