    return new Promise((resolve) => {
        try {
            const data = JSON.stringify(auditData);

            // Parse the URL to determine protocol
            const url = new URL(auditUrl);
            const isHttps = url.protocol === 'https:';
            const port = url.port || (isHttps ? 443 : 80);
            const options = {
                hostname: url.hostname,
                port: port,
                path: url.pathname,
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Content-Length': Buffer.byteLength(data)
                },
                // Add timeout to prevent hanging if service is not available
                timeout: 5000
            };

            const req = (isHttps ? https : http).request(options, (res) => {
                let responseData = '';

                res.on('data', (chunk) => {
                    responseData += chunk;
                });

                res.on('end', () => {
                    console.log(`✓ Audit service responded with status: ${res.statusCode}`);

                    if (res.statusCode >= 200 && res.statusCode < 300) {
                        console.log('✅ Audit data sent successfully');
                        resolve(true);
