#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Read DATABASE_URL from .env.test file
 * @returns {string|null} The DATABASE_URL or null if not found
 */
function readDatabaseUrlFromEnv() {
  const envFilePath = '.env.test';

  // Check if .env.test file exists
  if (!fs.existsSync(envFilePath)) {
    console.error(`Warning: Environment file '${envFilePath}' not found.`);
    return null;
  }

  try {
    // Read the .env.test file
    const envContent = fs.readFileSync(envFilePath, 'utf8');

    // Parse the file line by line
    const lines = envContent.split('\n');

    for (const line of lines) {
      // Skip comments and empty lines
      if (line.trim() === '' || line.trim().startsWith('#')) {
        continue;
      }

      // Look for DATABASE_URL
      if (line.startsWith('DATABASE_URL=')) {
        // Extract the value after '='
        const url = line.substring('DATABASE_URL='.length).trim();
        return url;
      }
    }

    console.error(`Warning: DATABASE_URL not found in '${envFilePath}'.`);
    return null;

  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return null;
  }
}

/**
 * Extract database connection details from URL for logging
 * @param {string} databaseUrl - The database connection URL
 * @returns {object} Parsed connection details
 */
function parseDatabaseUrl(databaseUrl) {
  try {
    // Simple URL parsing (for display purposes only)
    const url = new URL(databaseUrl);
    return {
      protocol: url.protocol.replace(':', ''),
      hostname: url.hostname,
      port: url.port || (url.protocol === 'postgres:' ? '5432' : 'unknown'),
      database: url.pathname.substring(1), // Remove leading '/'
      username: url.username || 'unknown'
    };
  } catch (error) {
    // If URL parsing fails, return basic info
    return {
      rawUrl: databaseUrl.substring(0, 50) + (databaseUrl.length > 50 ? '...' : ''),
      note: 'Could not fully parse URL'
    };
  }
}

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename in order.
 */
function main() {
  console.log('Migration script started...\n');

  // Step 1: Read DATABASE_URL from .env.test
  console.log('Step 1: Reading database configuration...');
  const databaseUrl = readDatabaseUrlFromEnv();

  if (databaseUrl) {
    const connectionDetails = parseDatabaseUrl(databaseUrl);

    if (connectionDetails.protocol && connectionDetails.hostname) {
      console.log(`✓ Connected to ${connectionDetails.protocol.toUpperCase()} database:`);
      console.log(`  Host: ${connectionDetails.hostname}:${connectionDetails.port}`);
      console.log(`  Database: ${connectionDetails.database}`);
      console.log(`  Username: ${connectionDetails.username}`);
    } else {
      console.log(`✓ Database URL found: ${connectionDetails.rawUrl}`);
    }
    console.log('');
  } else {
    console.log('⚠ Could not read DATABASE_URL from .env.test file\n');
  }

  // Step 2: Read migration files
  console.log('Step 2: Reading migration files...');
  const migrationsDir = './migrations';

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Directory '${migrationsDir}' does not exist.`);
    console.log('Please create a migrations directory with SQL files.');
    process.exit(1);
  }

  try {
    // Read all files from the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files (files ending with .sql)
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
      console.log(`No SQL files found in '${migrationsDir}' directory.`);
      return;
    }

    // Sort files alphabetically (assuming naming convention like 001_initial.sql, 002_add_users.sql)
    sqlFiles.sort();

    console.log(`✓ Found ${sqlFiles.length} SQL migration file(s):\n`);

    // Log each filename in order
    sqlFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });

    console.log('\n--- Summary ---');
    console.log(`Would apply ${sqlFiles.length} migration(s) in the order shown above.`);

    if (databaseUrl) {
      console.log('\nNote: This is a dry-run simulation. If executed, migrations would be applied to:');
      const details = parseDatabaseUrl(databaseUrl);
      if (details.database) {
        console.log(`  Database: ${details.database}`);
      }
    } else {
      console.log('\nNote: This is a dry-run simulation. Database connection details not available.');
    }

    console.log('\nTo actually execute the migrations, you would need to:');
    console.log('1. Establish a real database connection');
    console.log('2. Read and execute each SQL file');
    console.log('3. Track which migrations have been applied');

  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

// Run the main function if this script is executed directly
if (require.main === module) {
  main();
}

module.exports = { main, readDatabaseUrlFromEnv, parseDatabaseUrl };

