#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order
 */

class MigrationScript {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
    }

    /**
     * Get all migration files from the migrations directory
     * @returns {Array} Sorted array of migration file objects
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.log(`Migrations directory '${this.migrationsDir}' not found. Creating it...`);
                fs.mkdirSync(this.migrationsDir, { recursive: true });
                return [];
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir)
                .filter(file => file.endsWith('.sql'))
                .map(file => {
                    const filePath = path.join(this.migrationsDir, file);
                    return {
                        filename: file,
                        filepath: filePath,
                        timestamp: this.extractTimestamp(file)
                    };
                });

            // Sort by timestamp (numeric prefix in filename)
            return files.sort((a, b) => {
                return a.timestamp - b.timestamp;
            });
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            return [];
        }
    }

    /**
     * Extract timestamp/numeric prefix from filename
     * @param {string} filename - The migration filename
     * @returns {number} Extracted timestamp or 0 if not found
     */
    extractTimestamp(filename) {
        const match = filename.match(/^(\d+)_/);
        return match ? parseInt(match[1], 10) : 0;
    }

    /**
     * Read and log migration file content (optional - for demonstration)
     * @param {Object} migrationFile - Migration file object
     */
    logMigrationDetails(migrationFile) {
        try {
            const content = fs.readFileSync(migrationFile.filepath, 'utf8');
            const lineCount = content.split('\n').length;
            console.log(`  • ${migrationFile.filename} (${lineCount} lines)`);

            // Uncomment the next line if you want to see SQL content
            // console.log(`    SQL Preview: ${content.substring(0, 100)}...`);
        } catch (error) {
            console.log(`  • ${migrationFile.filename} (Error reading file: ${error.message})`);
        }
    }

    /**
     * Run the migration script
     */
    run() {
        console.log('Database Migration Script');
        console.log('='.repeat(40));
        console.log(`Looking for migrations in: ${path.resolve(this.migrationsDir)}`);
        console.log();

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            console.log('Please add .sql files to the migrations directory.');
            console.log('Files should be named like: 001_descriptive_name.sql, 002_next_migration.sql');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):`);
        console.log();

        // Log each migration file in order
        migrationFiles.forEach((migrationFile, index) => {
            console.log(`${index + 1}. ${migrationFile.filename}`);
            this.logMigrationDetails(migrationFile);
            console.log();
        });

        console.log('='.repeat(40));
        console.log('Summary:');
        console.log(`- Total migrations: ${migrationFiles.length}`);
        console.log(`- First migration: ${migrationFiles[0]?.filename || 'N/A'}`);
        console.log(`- Last migration: ${migrationFiles[migrationFiles.length - 1]?.filename || 'N/A'}`);
        console.log();
        console.log('Note: This script only logs what would be applied.');
        console.log('To actually apply migrations, you would need to:');
        console.log('1. Read each SQL file');
        console.log('2. Connect to your database');
        console.log('3. Execute the SQL statements');
        console.log('4. Track which migrations have been applied');
    }
}

// Run the script if called directly
if (require.main === module) {
    const script = new MigrationScript();
    script.run();
}

// Export for testing or programmatic use
module.exports = MigrationScript;

-- This migration doesn't have a numeric prefix
