#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.migrationFiles = [];
  }

  /**
   * Check if migrations directory exists
   */
  checkMigrationsDir() {
    if (!fs.existsSync(this.migrationsDir)) {
      console.error(`Migrations directory not found: ${this.migrationsDir}`);
      console.log('Creating migrations directory...');
      fs.mkdirSync(this.migrationsDir, { recursive: true });
      console.log('Migrations directory created. Add SQL migration files to begin.');
      return false;
    }
    return true;
  }

  /**
   * Read migration files from the migrations directory
   */
  readMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and sort them
      this.migrationFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort((a, b) => {
          // Try to extract numeric prefixes for natural sorting
          const numA = this.extractMigrationNumber(a);
          const numB = this.extractMigrationNumber(b);

          if (numA !== null && numB !== null) {
            return numA - numB;
          }

          // Fall back to alphabetical sorting
          return a.localeCompare(b);
        });

      return this.migrationFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      return [];
    }
  }

  /**
   * Extract migration number from filename (e.g., 001_initial.sql -> 1)
   */
  extractMigrationNumber(filename) {
    const match = filename.match(/^(\d+)_/);
    return match ? parseInt(match[1], 10) : null;
  }

  /**
   * Log migration files in order
   */
  logMigrations() {
    if (!this.checkMigrationsDir()) {
      return;
    }

    const files = this.readMigrationFiles();

    if (files.length === 0) {
      console.log('No SQL migration files found in migrations directory.');
      console.log(`Please add SQL files to: ${this.migrationsDir}`);
      return;
    }

    console.log('=== Database Migration Files ===');
    console.log(`Found ${files.length} migration file(s):\n`);

    files.forEach((file, index) => {
      const filePath = path.join(this.migrationsDir, file);
      const migrationNumber = this.extractMigrationNumber(file);
      const prefix = migrationNumber !== null ? `[${migrationNumber.toString().padStart(3, '0')}]` : '[   ]';

      console.log(`${prefix} ${index + 1}. ${file}`);

      // Optionally read and show a preview of the SQL content
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.trim().split('\n');
        const firstLine = lines[0].trim();

        if (firstLine) {
          const preview = firstLine.length > 50 
            ? firstLine.substring(0, 47) + '...' 
            : firstLine;
          console.log(`     Preview: ${preview}`);
        }
      } catch (error) {
        console.log(`     (Unable to read file)`);
      }

      console.log(''); // Add spacing between migrations
    });

    console.log('=== End of Migration Files ===');

    // Show execution summary
    console.log('\n[Execution Plan]');
    console.log(`Would apply ${files.length} migration(s) in the order shown above.`);
    console.log('\nTo actually execute these migrations, you would need to:');
    console.log('1. Connect to your database');
    console.log('2. Read each SQL file');
    console.log('3. Execute the SQL statements');
    console.log('4. Track completed migrations in a migrations table\n');
  }

  /**
   * Main function to run the migration script
   */
  run() {
    console.log('Database Migration Script');
    console.log('==========================\n');
    this.logMigrations();
  }
}

// Run the script if called directly
if (require.main === module) {
  const migrationRunner = new MigrationRunner();
  migrationRunner.run();
}

module.exports = MigrationRunner;

-- Add comments table
