        // Check for DATABASE_URL
        if (trimmedLine.startsWith('DATABASE_URL=')) {
          this.databaseUrl = trimmedLine.substring('DATABASE_URL='.length).trim();

          // Remove quotes if present
          if ((this.databaseUrl.startsWith('"') && this.databaseUrl.endsWith('"')) ||
              (this.databaseUrl.startsWith("'") && this.databaseUrl.endsWith("'"))) {
