/**
 * Mask sensitive parts of database URL for logging
 */
maskDatabaseUrl(url) {
  try {
    // Handle URLs with passwords (username:password@host)
    const passwordMatch = url.match(/:\/\/[^:]+:([^@]+)@/);

    if (passwordMatch && passwordMatch[1]) {
      // URL has a password, mask it
      return url.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');
    } else {
      // No password to mask or different format
      // Try to mask just the authentication part
      const authMatch = url.match(/:\/\/([^@]+)@/);
      if (authMatch && authMatch[1]) {
        // Has authentication (could be just username or token)
        return url.replace(/:\/\/([^@]+)@/, '://***@');
      }
      return url;
    }
  } catch (error) {
    // If parsing fails, return a generic masked version
    return '***masked-connection-string***';
  }
}

