#!/usr/bin/env node

/**
 * Database migration script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

class Migration {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        this.migrations = [];
    }

    /**
     * Get all migration files from the migrations directory
     * @returns {Array} Sorted array of migration file objects
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist`);
                process.exit(1);
            }

            // Read all files in the migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort((a, b) => {
                    // Extract numeric prefixes for sorting
                    const numA = this.extractMigrationNumber(a);
                    const numB = this.extractMigrationNumber(b);

                    if (numA !== null && numB !== null) {
                        return numA - numB;
                    }
                    // If no numbers found, sort alphabetically
                    return a.localeCompare(b);
                });

            // Create migration objects
            this.migrations = sqlFiles.map(file => ({
                filename: file,
                filepath: path.join(this.migrationsDir, file),
                timestamp: this.extractTimestamp(file),
                order: this.extractMigrationNumber(file)
            }));

            return this.migrations;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Extract migration number from filename
     * @param {string} filename - The migration filename
     * @returns {number|null} The migration number or null if not found
     */
    extractMigrationNumber(filename) {
        const match = filename.match(/^(\d+)_/);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Attempt to extract timestamp from filename
     * @param {string} filename - The migration filename
     * @returns {string|null} Formatted timestamp or filename if no timestamp
     */
    extractTimestamp(filename) {
        // Try to extract timestamp format like YYYYMMDD_HHMMSS
        const timestampMatch = filename.match(/(\d{8}_\d{6})/);
        if (timestampMatch) {
            const ts = timestampMatch[1];
            return `${ts.slice(0, 4)}-${ts.slice(4, 6)}-${ts.slice(6, 8)} ${ts.slice(9, 11)}:${ts.slice(11, 13)}:${ts.slice(13, 15)}`;
        }

        // Try to extract just date format like YYYYMMDD
        const dateMatch = filename.match(/(\d{8})/);
        if (dateMatch) {
            const date = dateMatch[1];
            return `${date.slice(0, 4)}-${date.slice(4, 6)}-${date.slice(6, 8)}`;
        }

        return filename;
    }

    /**
     * Log all migration files in order
     */
    logMigrations() {
        console.log('Database Migration Script');
        console.log('=========================');
        console.log(`Reading migrations from: ${this.migrationsDir}`);
        console.log('');

        const migrations = this.getMigrationFiles();

        if (migrations.length === 0) {
            console.log('No migration files found.');
            return;
        }

        console.log(`Found ${migrations.length} migration file(s):`);
        console.log('');

        // Log each migration file with its details
        migrations.forEach((migration, index) => {
            console.log(`${index + 1}. ${migration.filename}`);

            // Read and display the first few lines of the SQL file
            try {
                const content = fs.readFileSync(migration.filepath, 'utf8');
                const lines = content.split('\n').slice(0, 3);

                console.log('   SQL Preview:');
                lines.forEach(line => {
                    if (line.trim()) {
                        console.log(`     ${line.trim()}`);
                    }
                });

                // Add ellipsis if there are more lines
                if (content.split('\n').length > 3) {
                    console.log('     ...');
                }
            } catch (error) {
                console.log(`   Error reading file: ${error.message}`);
            }

            console.log('');
        });

        console.log('Summary:');
        console.log(`  Total migrations to apply: ${migrations.length}`);
        console.log(`  First migration: ${migrations[0].filename}`);
        console.log(`  Last migration: ${migrations[migrations.length - 1].filename}`);
        console.log('');

        // Ask for confirmation (simulated - in a real system, this would execute the migrations)
        console.log('Note: This script only logs the migrations.');
        console.log('      To actually apply migrations, you would need to:');
        console.log('      1. Connect to your database');
        console.log('      2. Execute each SQL file in order');
        console.log('      3. Track which migrations have been applied');
        console.log('');
        console.log('Ready to apply these migrations? [DRY RUN - no changes will be made]');
    }

    /**
     * Simulate applying migrations (doesn't actually execute SQL)
     */
    simulateApplyMigrations() {
        const migrations = this.getMigrationFiles();

        console.log('\nSimulating migration application:');
        console.log('--------------------------------');

        migrations.forEach((migration, index) => {
            console.log(`[${index + 1}/${migrations.length}] Applying: ${migration.filename}`);

            // In a real implementation, you would:
            // 1. Check if migration has already been applied
            // 2. Read the SQL file
            // 3. Execute the SQL against the database
            // 4. Record the migration as applied

            console.log(`   ✓ Would execute migration: ${migration.filename}`);
        });

        console.log('\n✓ All migrations would be applied successfully!');
    }
}

/**
 * Main function
 */
function main() {
    const migration = new Migration();

    // Parse command line arguments
    const args = process.argv.slice(2);

    if (args.includes('--simulate') || args.includes('-s')) {
        migration.logMigrations();
        migration.simulateApplyMigrations();
    } else if (args.includes('--help') || args.includes('-h')) {
        showHelp();
    } else {
        migration.logMigrations();
    }
}

/**
 * Show help information
 */
function showHelp() {
    console.log(`
Database Migration Script Usage:
node migrate.js [options]

Options:
  -h, --help      Show this help message
  -s, --simulate  Log migrations and simulate applying them
  --list          List all migration files (default behavior)

Examples:
  node migrate.js               List all migration files in order
  node migrate.js --simulate    List and simulate applying migrations
  node migrate.js --help        Show this help message
    `);
}

// Run the script
if (require.main === module) {
    main();
}

module.exports = Migration;

