/**
 * Load environment variables from .env.test file
 * @returns {object} Loaded environment variables
 */
loadEnvFile() {
    const envVars = {};

    try {
        if (!fs.existsSync(this.envFile)) {
            console.error(`Error: Environment file '${this.envFile}' does not exist`);
            console.log('Looking for .env.test in:', path.resolve(this.envFile));
            return envVars;
        }

        const envContent = fs.readFileSync(this.envFile, 'utf8');
        const lines = envContent.split('\n');

        lines.forEach(line => {
            line = line.trim();

            // Skip comments and empty lines
            if (!line || line.startsWith('#')) {
                return;
            }

            // Parse key=value pairs
            const match = line.match(/^([^=]+)=(.*)$/);
            if (match) {
                const key = match[1].trim();
                const value = match[2].trim();

                // Remove quotes if present
                const cleanedValue = value.replace(/^['"]|['"]$/g, '');
                envVars[key] = cleanedValue;
            }
        });

        return envVars;
    } catch (error) {
        console.error(`Error reading ${this.envFile}: ${error.message}`);
        return envVars;
    }
}

