        console.log('Cannot proceed without valid database configuration.');
        return;
    }

    // Parse command line arguments
    const args = process.argv.slice(2);

    if (args.includes('--simulate') || args.includes('-s')) {
        // Log migrations
        migration.logMigrations();

        // Simulate applying migrations
        migration.simulateApplyMigrations();
    } else if (args.includes('--help') || args.includes('-h')) {
        showHelp();
    } else {
        migration.logMigrations();
