#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

// Configuration
const MIGRATIONS_DIR = './migrations';

/**
 * Read SQL files from migrations directory and return them sorted
 * @returns {Array} Array of migration file objects with filename and filepath
 */
function getMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
            process.exit(1);
        }

        // Read all files in migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files (files ending with .sql)
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log(`No SQL files found in '${MIGRATIONS_DIR}' directory.`);
            return [];
        }

        // Create file objects with filename and full path
        const migrationFiles = sqlFiles.map(filename => ({
            filename,
            filepath: path.join(MIGRATIONS_DIR, filename)
        }));

        // Sort files alphabetically (which preserves timestamp order if using timestamps)
        migrationFiles.sort((a, b) => a.filename.localeCompare(b.filename));

        return migrationFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }
}

/**
 * Log migration files that would be applied
 * @param {Array} migrationFiles - Array of migration file objects
 */
function logMigrations(migrationFiles) {
    console.log('\n=== Database Migration Script ===');
    console.log('Reading SQL files from:', MIGRATIONS_DIR);
    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    if (migrationFiles.length === 0) {
        return;
    }

    console.log('The following migrations would be applied in order:');
    console.log('----------------------------------------------------');

    migrationFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file.filename}`);
    });

    console.log('----------------------------------------------------');
    console.log('\nNote: This is a dry run - no actual database operations are performed.');
    console.log('To actually apply migrations, you would need to implement database connection logic.');
}

/**
 * Main function
 */
function main() {
    console.log('Starting migration script...');

    // Get migration files
    const migrationFiles = getMigrationFiles();

    // Log the files that would be applied
    logMigrations(migrationFiles);

    // For demonstration, also show the content of each file if user wants to see
    if (migrationFiles.length > 0) {
        console.log('\nTo view migration content, implement:');
        console.log('  migrationFiles.forEach(file => {');
        console.log('    const content = fs.readFileSync(file.filepath, \'utf8\');');
        console.log('    console.log(`\\n${file.filename}:`);');
        console.log('    console.log(content);');
        console.log('  });');
    }
}

// Run the script
if (require.main === module) {
    main();
}

module.exports = { getMigrationFiles, logMigrations };

