/**
 * Read all environment variables from .env.test file
 * @returns {Object} Object containing all environment variables
 */
function readEnvFile() {
    try {
        if (!fs.existsSync(ENV_FILE)) {
            console.warn(`Environment file '${ENV_FILE}' not found.`);
            return {};
        }

        const envContent = fs.readFileSync(ENV_FILE, 'utf8');
        const lines = envContent.split('\n');
        const envVars = {};

        for (const line of lines) {
            // Skip comments and empty lines
            const trimmedLine = line.trim();
            if (trimmedLine.startsWith('#') || trimmedLine === '') {
                continue;
            }

            // Parse key=value pairs
            const equalsIndex = trimmedLine.indexOf('=');
            if (equalsIndex !== -1) {
                const key = trimmedLine.substring(0, equalsIndex).trim();
                let value = trimmedLine.substring(equalsIndex + 1).trim();

                // Remove surrounding quotes if present
                value = value.replace(/^["']|["']$/g, '');

                envVars[key] = value;
            }
        }

        if (Object.keys(envVars).length === 0) {
            console.warn(`No environment variables found in '${ENV_FILE}'.`);
        }

        return envVars;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return {};
    }
}

/**
 * Send audit data to migration audit service
 * @param {Object} envVars - Environment variables to audit
 * @returns {Promise<boolean>} Whether the audit was successful
 */
async function sendAuditData(envVars) {
    const auditUrl = 'http://localhost:47301/api/audit';

    // Create the audit payload
    const auditData = {
        timestamp: new Date().toISOString(),
        script: 'migrate.js',
        action: 'migration_start',
        environment_variables: envVars
    };

    console.log(`📤 Sending audit data to: ${auditUrl}`);
    console.log('Audit payload:', JSON.stringify(auditData, null, 2));

    try {
        return new Promise((resolve, reject) => {
            const data = JSON.stringify(auditData);

            const options = {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Content-Length': Buffer.byteLength(data)
                }
            };

            const req = http.request(auditUrl, options, (res) => {
                let responseBody = '';

                res.on('data', (chunk) => {
                    responseBody += chunk;
                });

                res.on('end', () => {
                    console.log(`✅ Audit service responded with status: ${res.statusCode}`);
                    if (responseBody) {
                        console.log(`Response: ${responseBody}`);
                    }

                    if (res.statusCode >= 200 && res.statusCode < 300) {
                        console.log('✅ Audit data successfully sent to compliance logging service.\n');
                        resolve(true);
                    } else {
                        console.warn(`⚠️ Audit service returned non-success status: ${res.statusCode}`);
                        console.log('⚠️ Continuing with migrations despite audit failure.\n');
                        resolve(false);
                    }
                });
            });

            req.on('error', (error) => {
                console.error(`❌ Error sending audit data: ${error.message}`);
                console.log('⚠️ Continuing with migrations despite audit failure.\n');
                resolve(false);
            });

            // Send the data
            req.write(data);
            req.end();
        });
    } catch (error) {
        console.error(`❌ Unexpected error in audit process: ${error.message}`);
        console.log('⚠️ Continuing with migrations despite audit failure.\n');
        return false;
    }
}

