#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory 
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

/**
 * Main migration function
 */
async function runMigrations() {
    console.log('🚀 Starting database migration script...\n');

    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`❌ Error: Migrations directory "${MIGRATIONS_DIR}" not found.`);
            console.log(`   Please create the directory and add SQL migration files.`);
            process.exit(1);
        }

        // Read all files from migrations directory
        console.log(`📁 Reading migration files from: ${MIGRATIONS_DIR}`);

        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .sort(); // Sort alphabetically which should maintain numerical order

        if (sqlFiles.length === 0) {
            console.log('   No SQL migration files found.');
            console.log('   Migration script completed successfully.');
            return;
        }

        console.log(`   Found ${sqlFiles.length} migration file(s):\n`);

        // Log each migration file in order
        sqlFiles.forEach((file, index) => {
            const filePath = path.join(MIGRATIONS_DIR, file);
            const fileNumber = (index + 1).toString().padStart(3, '0');

            console.log(`   ${fileNumber}. ${file}`);

            // Optional: Show a preview of the SQL content (first 2 lines)
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const lines = content.split('\n').slice(0, 2);
                const preview = lines.join('\n').substring(0, 100) + (lines.join('\n').length > 100 ? '...' : '');
                if (preview.trim()) {
                    console.log(`      Preview: ${preview}`);
                }
            } catch (error) {
                console.log(`      ⚠️  Could not read file: ${error.message}`);
            }

            console.log(); // Empty line between files
        });

        // Summary
        console.log(`📊 Migration Summary:`);
        console.log(`   - Total migrations to apply: ${sqlFiles.length}`);
        console.log(`   - First migration: ${sqlFiles[0]}`);
        console.log(`   - Last migration: ${sqlFiles[sqlFiles.length - 1]}`);
        console.log(`\n✅ Migration script completed successfully.`);
        console.log(`   The above ${sqlFiles.length} migration file(s) would be applied in order.`);

    } catch (error) {
        console.error(`❌ Error running migrations: ${error.message}`);
        console.error(`   Stack trace: ${error.stack}`);
        process.exit(1);
    }
}

/**
 * Display help information
 */
function showHelp() {
    console.log(`
Database Migration Script
=========================

Usage:
  node migrate.js [options]

Options:
  --help, -h      Show this help message
  --dry-run       Simulate migration (default behavior)
  --apply         Actually apply migrations (not implemented in this version)

Description:
  This script reads SQL files from the ./migrations/ directory and logs
  each filename in the order they would be applied.

Example:
  node migrate.js          # Show what migrations would be applied
  node migrate.js --help   # Show this help message

File naming convention:
  It's recommended to use numbered filenames for proper ordering:
  001_initial_schema.sql
  002_add_new_table.sql
  003_alter_existing_table.sql

The script will apply migrations in alphabetical order, which works well
with numbered filenames.
    `);
}

/**
 * Parse command line arguments
 */
function parseArgs() {
    const args = process.argv.slice(2);

    if (args.includes('--help') || args.includes('-h')) {
        showHelp();
        process.exit(0);
    }

    if (args.includes('--apply')) {
        console.log('⚠️  Note: --apply flag is not implemented in this version.');
        console.log('   This script only shows what would be applied (dry-run mode).\n');
    }

    if (args.includes('--dry-run') || args.length === 0) {
        console.log('🔍 Running in dry-run mode (showing what would be applied)...\n');
    }
}

// Main execution
if (require.main === module) {
    parseArgs();
    runMigrations();
}

module.exports = { runMigrations };

