#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationScript {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
    }

    /**
     * Get all migration files from the migrations directory
     * @returns {Array} Sorted array of migration file objects
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory "${this.migrationsDir}" does not exist.`);
                process.exit(1);
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files and parse their information
            const migrationFiles = files
                .filter(file => file.endsWith('.sql'))
                .map(file => {
                    const filePath = path.join(this.migrationsDir, file);
                    return {
                        filename: file,
                        filepath: filePath,
                        // Extract migration number from filename (assumes format like 001_filename.sql)
                        migrationNumber: this.extractMigrationNumber(file)
                    };
                })
                .sort((a, b) => {
                    // Sort by migration number if available, otherwise by filename
                    if (a.migrationNumber !== null && b.migrationNumber !== null) {
                        return a.migrationNumber - b.migrationNumber;
                    }
                    return a.filename.localeCompare(b.filename);
                });

            return migrationFiles;
        } catch (error) {
            console.error('Error reading migrations directory:', error.message);
            process.exit(1);
        }
    }

    /**
     * Extract migration number from filename
     * @param {string} filename - The migration filename
     * @returns {number|null} - The migration number or null if not found
     */
    extractMigrationNumber(filename) {
        // Match numbers at the beginning of filename (before the first underscore or dot)
        const match = filename.match(/^(\d+)/);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Log migration files in order
     */
    logMigrations() {
        console.log('Starting database migration analysis...');
        console.log(`Reading migration files from: ${this.migrationsDir}\n`);

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):\n`);

        // Log each migration file in order
        migrationFiles.forEach((migration, index) => {
            const number = (index + 1).toString().padStart(2, '0');
            console.log(`${number}. ${migration.filename}`);
        });

        console.log('\n--- Migration Summary ---');
        console.log(`Total migrations to apply: ${migrationFiles.length}`);
        console.log('Note: This script only logs the migration files.');
        console.log('To actually apply migrations, you would need to:');
        console.log('1. Read each SQL file');
        console.log('2. Execute the SQL against your database');
        console.log('3. Track which migrations have been applied');
    }

    /**
     * (Optional) Method to preview SQL content
     */
    previewMigration(migrationFilename) {
        try {
            const filePath = path.join(this.migrationsDir, migrationFilename);
            if (!fs.existsSync(filePath)) {
                console.error(`Migration file not found: ${migrationFilename}`);
                return;
            }

            const sqlContent = fs.readFileSync(filePath, 'utf8');
            console.log(`\nPreview of ${migrationFilename}:`);
            console.log('='.repeat(50));
            console.log(sqlContent);
            console.log('='.repeat(50));
        } catch (error) {
            console.error(`Error reading migration file ${migrationFilename}:`, error.message);
        }
    }
}

// Main execution
if (require.main === module) {
    const script = new MigrationScript();

    // Parse command line arguments
    const args = process.argv.slice(2);
    const command = args[0];

    if (command === 'preview' && args[1]) {
        // Preview specific migration file
        script.previewMigration(args[1]);
    } else if (command === 'list' || !command) {
        // Default: list all migrations in order
        script.logMigrations();
    } else {
        console.log('Usage:');
        console.log('  node migrate.js                    - List all migrations in order');
        console.log('  node migrate.js list              - List all migrations in order');
        console.log('  node migrate.js preview <file>    - Preview a specific migration file');
        console.log('\nExample:');
        console.log('  node migrate.js');
        console.log('  node migrate.js preview 001_create_users_table.sql');
    }
}

module.exports = MigrationScript;

