#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        this.ensureMigrationsDirectory();
    }

    /**
     * Ensure the migrations directory exists
     */
    ensureMigrationsDirectory() {
        if (!fs.existsSync(this.migrationsDir)) {
            fs.mkdirSync(this.migrationsDir, { recursive: true });
            console.log(`Created migrations directory: ${this.migrationsDir}`);
        }
    }

    /**
     * Get all SQL migration files from the migrations directory
     * @returns {Array} Sorted array of migration file paths
     */
    getMigrationFiles() {
        try {
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .map(file => ({
                    name: file,
                    path: path.join(this.migrationsDir, file)
                }))
                .sort((a, b) => a.name.localeCompare(b.name));

            return sqlFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            return [];
        }
    }

    /**
     * Parse migration number from filename (if using numeric prefixes like 001_create_users.sql)
     * @param {string} filename 
     * @returns {number|null} Migration number or null if not numeric
     */
    parseMigrationNumber(filename) {
        const match = filename.match(/^(\d+)_/);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Sort migration files in the order they should be applied
     * @param {Array} migrationFiles 
     * @returns {Array} Sorted migration files
     */
    sortMigrationFiles(migrationFiles) {
        return migrationFiles.sort((a, b) => {
            const numA = this.parseMigrationNumber(a.name);
            const numB = this.parseMigrationNumber(b.name);

            // If both have numeric prefixes, sort by number
            if (numA !== null && numB !== null) {
                return numA - numB;
            }

            // If only one has numeric prefix, put it first
            if (numA !== null && numB === null) {
                return -1;
            }
            if (numA === null && numB !== null) {
                return 1;
            }

            // Otherwise sort alphabetically
            return a.name.localeCompare(b.name);
        });
    }

    /**
     * Display migration files in order they would be applied
     */
    logMigrationFiles() {
        console.log('=== Migration Script ===');
        console.log(`Reading migrations from: ${this.migrationsDir}\n`);

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            console.log('To create a migration, add SQL files to the migrations directory.');
            return;
        }

        const sortedFiles = this.sortMigrationFiles(migrationFiles);

        console.log(`Found ${sortedFiles.length} migration file(s):\n`);

        sortedFiles.forEach((file, index) => {
            const migrationNum = this.parseMigrationNumber(file.name);
            const prefix = migrationNum !== null ? `${migrationNum.toString().padStart(3, '0')}. ` : '     ';
            console.log(`${index + 1}. ${prefix}${file.name}`);
        });

        console.log('\nThese migrations would be applied in the order shown above.');
    }

    /**
     * Run the migration script
     */
    run() {
        try {
            this.logMigrationFiles();
        } catch (error) {
            console.error(`Migration script failed: ${error.message}`);
            process.exit(1);
        }
    }
}

// If this script is run directly (not imported as a module)
if (require.main === module) {
    const migrationScript = new MigrationScript();
    migrationScript.run();
}

module.exports = MigrationScript;

-- Migration 1: Create users table
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Add an index for faster username lookups
CREATE INDEX idx_users_username ON users(username);

-- Migration 3: Create comments table
CREATE TABLE IF NOT EXISTS comments (
    id SERIAL PRIMARY KEY,
    post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
    user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    content TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Add composite index for faster post comments retrieval
CREATE INDEX idx_comments_post_id ON comments(post_id);

