                continue;
            }

            // Look for DATABASE_URL
            if (trimmedLine.startsWith('DATABASE_URL=')) {
                const url = trimmedLine.substring('DATABASE_URL='.length).trim();

                // Remove quotes if present
                const cleanUrl = url.replace(/^['"]|['"]$/g, '');

                console.log(`Found DATABASE_URL in ${path.basename(this.envTestPath)}`);
                return cleanUrl;
            }
        }

        console.log(`DATABASE_URL not found in ${path.basename(this.envTestPath)}`);
        return null;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return null;
    }
}

/**
 * Parse database URL and extract connection details
 * @param {string} databaseUrl 
 * @returns {Object} Connection details
 */
parseDatabaseUrl(databaseUrl) {
    try {
        const url = new URL(databaseUrl);

        return {
            protocol: url.protocol.replace(':', ''),
            host: url.hostname,
            port: url.port || (url.protocol === 'postgres:' ? '5432' : '3306'),
            database: url.pathname.replace('/', ''),
            username: url.username,
            hasPassword: !!url.password,
            // Don't log the actual password
            passwordSet: !!url.password
        };
    } catch (error) {
        console.error(`Error parsing DATABASE_URL: ${error.message}`);
        return null;
    }
}

