        }

    } catch (error) {
        console.error(`✗ Failed to send audit data: ${error.message}`);
        console.log('Continuing with migrations...');
        return false;
    }
}

/**
 * Make HTTP request with retry logic
 * @param {string} url Request URL
 * @param {string} method HTTP method
 * @param {string} body Request body
 * @param {Object} headers Request headers
 * @returns {Promise<Object>} Response object with statusCode and body
 */
makeHttpRequest(url, method, body, headers = {}) {
    return new Promise((resolve, reject) => {
        const urlObj = new URL(url);
        const isHttps = urlObj.protocol === 'https:';

        const requestOptions = {
            hostname: urlObj.hostname,
            port: urlObj.port || (isHttps ? 443 : 80),
            path: urlObj.pathname + urlObj.search,
            method: method,
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(body),
                'User-Agent': 'MigrationAudit/1.0',
                ...headers
            },
            timeout: 10000 // 10 seconds timeout
        };

        const httpModule = isHttps ? https : http;

        const req = httpModule.request(requestOptions, (res) => {
            let responseBody = '';

            res.on('data', (chunk) => {
                responseBody += chunk;
            });

            res.on('end', () => {
                resolve({
                    statusCode: res.statusCode,
                    headers: res.headers,
                    body: responseBody
                });
            });
        });

        req.on('error', (error) => {
            reject(error);
        });

        req.on('timeout', () => {
            req.destroy();
            reject(new Error('Request timeout'));
        });

        req.write(body);
        req.end();
    });
}

