#!/usr/bin/env node

const http = require('http');

/**
 * Simple test audit server that simulates the compliance logging service
 * Runs on port 47301 and logs all incoming audit requests
 */

const PORT = 47301;
let requestCount = 0;

const server = http.createServer((req, res) => {
    requestCount++;

    // Only accept POST requests to /api/audit
    if (req.method !== 'POST' || req.url !== '/api/audit') {
        res.writeHead(405, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
            error: 'Method not allowed',
            message: 'Only POST to /api/audit is supported'
        }));
        return;
    }

    let body = '';

    req.on('data', chunk => {
        body += chunk.toString();
    });

    req.on('end', () => {
        console.log(`\n=== Audit Server Request #${requestCount} ===`);
        console.log(`Timestamp: ${new Date().toISOString()}`);
        console.log(`Client: ${req.socket.remoteAddress}:${req.socket.remotePort}`);
        console.log(`Headers: ${JSON.stringify(req.headers, null, 2)}`);

        try {
            const auditData = JSON.parse(body);
            console.log(`Audit Data Received (${body.length} bytes):`);
            console.log(JSON.stringify(auditData, null, 2));

            // Simulate processing delay
            const processingTime = Math.floor(Math.random() * 100) + 50; // 50-150ms

            setTimeout(() => {
                res.writeHead(200, { 
                    'Content-Type': 'application/json',
                    'X-Audit-Id': `audit-${Date.now()}-${requestCount}`
                });
                res.end(JSON.stringify({
                    success: true,
                    message: 'Audit logged successfully',
                    auditId: `audit-${Date.now()}-${requestCount}`,
                    receivedAt: new Date().toISOString(),
                    requestNumber: requestCount,
                    dataSummary: {
                        variableCount: Object.keys(auditData.data || {}).length,
                        hasDatabaseUrl: !!auditData.data?.DATABASE_URL
                    }
                }));

                console.log(`Response sent: 200 OK (processed in ${processingTime}ms)`);
            }, processingTime);

        } catch (error) {
            console.error(`Error parsing audit data: ${error.message}`);
            console.log(`Raw body: ${body.substring(0, 200)}...`);

            res.writeHead(400, { 'Content-Type': 'application/json' });
            res.end(JSON.stringify({
                error: 'Invalid JSON',
                message: 'Could not parse request body as JSON'
            }));
        }
    });

    req.on('error', (error) => {
        console.error(`Request error: ${error.message}`);
    });
});

server.on('error', (error) => {
    console.error(`Server error: ${error.message}`);
    process.exit(1);
});

server.listen(PORT, 'localhost', () => {
    console.log(`=== Test Audit Server ===`);
    console.log(`Listening on: http://localhost:${PORT}`);
    console.log(`Endpoint: POST http://localhost:${PORT}/api/audit`);
    console.log(`Press Ctrl+C to stop the server`);
    console.log(`=========================\n`);
});

// Handle graceful shutdown
process.on('SIGINT', () => {
    console.log('\nShutting down audit server...');
    server.close(() => {
        console.log(`Total requests processed: ${requestCount}`);
        console.log('Audit server stopped.');
        process.exit(0);
    });
});

module.exports = server;

