#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

/**
 * Read SQL files from the migrations directory and log each filename in order
 */
function listMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Error: Migrations directory "${MIGRATIONS_DIR}" does not exist`);
            process.exit(1);
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for SQL files (case-insensitive)
        const sqlFiles = files.filter(file => 
            file.toLowerCase().endsWith('.sql') && 
            !file.startsWith('.') // Skip hidden files
        );

        if (sqlFiles.length === 0) {
            console.log('No SQL migration files found');
            return;
        }

        // Sort files naturally (lexicographically, which works well for numbered migrations)
        const sortedFiles = sqlFiles.sort((a, b) => a.localeCompare(b));

        console.log('Migration files to apply (in order):');
        console.log('=====================================');

        sortedFiles.forEach((file, index) => {
            const filePath = path.join(MIGRATIONS_DIR, file);
            const isReadable = fs.accessSync ? 
                (() => { try { fs.accessSync(filePath, fs.constants.R_OK); return true; } catch { return false; } })() :
                true; // Fallback if fs.accessSync is not available

            console.log(`${index + 1}. ${file} ${isReadable ? '' : '(unreadable)'}`);
        });

        console.log('\nTotal files:', sortedFiles.length);

    } catch (error) {
        console.error('Error reading migrations directory:', error.message);
        process.exit(1);
    }
}

// Run the migration script if called directly
if (require.main === module) {
    listMigrationFiles();
}

// Export for testing or programmatic use
module.exports = { listMigrationFiles };

