#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Read SQL files from the migrations directory and log each filename in order
 * @param {string} migrationsDir - Path to the migrations directory (default: './migrations')
 */
function listMigrationFiles(migrationsDir = './migrations') {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.error(`Error: Migrations directory "${migrationsDir}" does not exist`);
            return false;
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files (case-insensitive)
        const sqlFiles = files.filter(file => 
            file.toLowerCase().endsWith('.sql') && 
            !file.startsWith('.') // Skip hidden files
        );

        if (sqlFiles.length === 0) {
            console.log(`No SQL migration files found in "${migrationsDir}"`);
            return true;
        }

        // Sort files naturally (lexicographically, which works well for numbered migrations)
        const sortedFiles = sqlFiles.sort((a, b) => a.localeCompare(b));

        console.log(`Migration files to apply from "${migrationsDir}" (in order):`);
        console.log('='.repeat(60));

        sortedFiles.forEach((file, index) => {
            const filePath = path.join(migrationsDir, file);
            let isReadable = true;
            let fileSize = 'unknown';

            try {
                // Check if file is readable and get its size
                fs.accessSync(filePath, fs.constants.R_OK);
                const stats = fs.statSync(filePath);
                fileSize = `${Math.ceil(stats.size / 1024)} KB`;
            } catch (error) {
                isReadable = false;
            }

            console.log(`${(index + 1).toString().padStart(3)}. ${file.padEnd(40)} ${isReadable ? `(${fileSize})` : '(unreadable)'}`);
        });

        console.log('\nTotal files:', sortedFiles.length);
        return true;

    } catch (error) {
        console.error(`Error reading migrations directory "${migrationsDir}":`, error.message);
        return false;
    }
}

/**
 * Parse command line arguments
 */
function parseArguments() {
    const args = process.argv.slice(2);
    const options = {
        migrationsDir: './migrations',
        help: false
    };

    for (let i = 0; i < args.length; i++) {
        const arg = args[i];

        if (arg === '--dir' || arg === '-d') {
            if (i + 1 < args.length) {
                options.migrationsDir = args[i + 1];
                i++;
            }
        } else if (arg === '--help' || arg === '-h') {
            options.help = true;
        } else if (!arg.startsWith('-')) {
            // Treat standalone argument as directory path
            options.migrationsDir = arg;
        }
    }

    return options;
}

/**
 * Display help information
 */
function showHelp() {
    console.log(`
Migration Script - List SQL files in order

Usage:
  node migrate.js [options] [directory]

Arguments:
  directory               Path to migrations directory (default: ./migrations)

Options:
  -d, --dir <directory>   Specify migrations directory
  -h, --help              Show this help message

Examples:
  node migrate.js                         # List files in ./migrations
  node migrate.js ./my-migrations         # List files in ./my-migrations
  node migrate.js --dir ./sql-migrations  # List files in ./sql-migrations
  node migrate.js -h                      # Show help

Description:
  This script reads all .sql files from the specified directory,
  sorts them in natural order, and displays them with their sizes.
    `);
}

// Run the migration script if called directly
if (require.main === module) {
    const options = parseArguments();

    if (options.help) {
        showHelp();
        process.exit(0);
    }

    const success = listMigrationFiles(options.migrationsDir);
    process.exit(success ? 0 : 1);
}

// Export for testing or programmatic use
module.exports = { listMigrationFiles, parseArguments, showHelp };

