#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Read and parse environment variables from .env.test file
 * @returns {object} Object containing environment variables
 */
function readEnvFile(envFilePath = '.env.test') {
    const envVars = {};

    try {
        if (!fs.existsSync(envFilePath)) {
            console.warn(`Warning: Environment file "${envFilePath}" does not exist`);
            return envVars;
        }

        const content = fs.readFileSync(envFilePath, 'utf8');
        const lines = content.split('\n');

        for (const line of lines) {
            // Skip comments and empty lines
            const trimmedLine = line.trim();
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse key=value pairs
            const [key, ...valueParts] = trimmedLine.split('=');
            if (key && valueParts.length > 0) {
                const value = valueParts.join('=').trim();
                envVars[key.trim()] = value;
            }
        }

        return envVars;
    } catch (error) {
        console.warn(`Warning: Could not read environment file "${envFilePath}":`, error.message);
        return envVars;
    }
}

/**
 * Extract database connection details from DATABASE_URL
 * @param {string} databaseUrl - Database connection URL
 * @returns {object} Parsed connection details
 */
function parseDatabaseUrl(databaseUrl) {
    try {
        // Parse the URL
        const url = new URL(databaseUrl);

        return {
            protocol: url.protocol.replace(':', ''),
            username: url.username,
            password: url.password ? '***' + url.password.slice(-4) : 'none',
            hostname: url.hostname,
            port: url.port,
            database: url.pathname.replace('/', ''),
            fullUrl: databaseUrl.replace(/:[^:@]*@/, ':***@') // Mask password in logs
        };
    } catch (error) {
        console.warn(`Warning: Could not parse DATABASE_URL:`, error.message);
        return null;
    }
}

/**
 * Log database connection success message
 * @param {object} connectionDetails - Parsed connection details
 */
function logConnectionSuccess(connectionDetails) {
    if (!connectionDetails) {
        console.error('Error: No valid database connection details found');
        return false;
    }

    console.log('='.repeat(60));
    console.log('DATABASE CONNECTION');
    console.log('='.repeat(60));
    console.log(`✓ Successfully resolved database connection from .env.test`);
    console.log(`  Protocol: ${connectionDetails.protocol}`);
    console.log(`  Username: ${connectionDetails.username}`);
    console.log(`  Password: ${connectionDetails.password}`);
    console.log(`  Host: ${connectionDetails.hostname}:${connectionDetails.port}`);
    console.log(`  Database: ${connectionDetails.database}`);
    console.log(`  URL: ${connectionDetails.fullUrl}`);
    console.log('');

    return true;
}

/**
 * Read SQL files from the migrations directory and log each filename in order
 * @param {string} migrationsDir - Path to the migrations directory (default: './migrations')
 * @param {string} envFilePath - Path to the environment file (default: '.env.test')
 */
function listMigrationFiles(migrationsDir = './migrations', envFilePath = '.env.test') {
    try {
        // Read environment variables first
        console.log('Initializing migration script...\n');
        const envVars = readEnvFile(envFilePath);

        // Check for DATABASE_URL
        const databaseUrl = envVars.DATABASE_URL;
        if (!databaseUrl) {
            console.warn(`Warning: DATABASE_URL not found in "${envFilePath}"`);
        } else {
            const connectionDetails = parseDatabaseUrl(databaseUrl);
            if (!logConnectionSuccess(connectionDetails)) {
                console.warn('Continuing without database connection...\n');
            }
        }

        // Check if migrations directory exists
        if (!fs.existsSync(migrationsDir)) {
            console.error(`Error: Migrations directory "${migrationsDir}" does not exist`);
            return false;
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files (case-insensitive)
        const sqlFiles = files.filter(file => 
            file.toLowerCase().endsWith('.sql') && 
            !file.startsWith('.') // Skip hidden files
        );

        if (sqlFiles.length === 0) {
            console.log(`No SQL migration files found in "${migrationsDir}"`);
            return true;
        }

        // Sort files naturally (lexicographically, which works well for numbered migrations)
        const sortedFiles = sqlFiles.sort((a, b) => a.localeCompare(b));

        console.log(`Migration files to apply from "${migrationsDir}" (in order):`);
        console.log('='.repeat(60));

        sortedFiles.forEach((file, index) => {
            const filePath = path.join(migrationsDir, file);
            let isReadable = true;
            let fileSize = 'unknown';

            try {
                // Check if file is readable and get its size
                fs.accessSync(filePath, fs.constants.R_OK);
                const stats = fs.statSync(filePath);
                fileSize = `${Math.ceil(stats.size / 1024)} KB`;
            } catch (error) {
                isReadable = false;
            }

            console.log(`${(index + 1).toString().padStart(3)}. ${file.padEnd(40)} ${isReadable ? `(${fileSize})` : '(unreadable)'}`);
        });

        console.log('\nTotal files:', sortedFiles.length);
        return true;

    } catch (error) {
        console.error(`Error reading migrations directory "${migrationsDir}":`, error.message);
        return false;
    }
}

