#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        this.migrations = [];
    }

    /**
     * Get all migration files from the migrations directory
     * @returns {Array} Sorted list of migration file names
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory not found at ${this.migrationsDir}`);
                console.log('Creating migrations directory...');
                fs.mkdirSync(this.migrationsDir, { recursive: true });
                console.log('No migration files found. Add .sql files to the migrations/ directory.');
                return [];
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            if (sqlFiles.length === 0) {
                console.log('No .sql migration files found in the migrations/ directory.');
                return [];
            }

            // Sort files alphabetically (which typically corresponds to chronological order)
            const sortedFiles = sqlFiles.sort((a, b) => {
                // Try to extract numbers from filenames for better sorting
                const aNum = this.extractNumber(a);
                const bNum = this.extractNumber(b);

                if (aNum !== null && bNum !== null) {
                    return aNum - bNum;
                }

                // Fall back to alphabetical sort
                return a.localeCompare(b);
            });

            return sortedFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            return [];
        }
    }

    /**
     * Extract numeric prefix from filename
     * @param {string} filename - The filename to extract from
     * @returns {number|null} - The extracted number or null if not found
     */
    extractNumber(filename) {
        const match = filename.match(/^(\d+)/);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('=== Database Migration Script ===');
        console.log(`Reading migration files from: ${this.migrationsDir}\n`);

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files to apply.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s):`);
        console.log('='.repeat(50));

        migrationFiles.forEach((file, index) => {
            const filePath = path.join(this.migrationsDir, file);
            const fileStat = fs.statSync(filePath);
            const fileSize = (fileStat.size / 1024).toFixed(2);

            console.log(`${index + 1}. ${file}`);
            console.log(`   Path: ${filePath}`);
            console.log(`   Size: ${fileSize} KB`);

            // Log a preview of the SQL content (first 3 lines)
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const lines = content.split('\n').slice(0, 3);
                console.log(`   Preview: ${lines.join(' ').substring(0, 100)}...`);
            } catch (error) {
                console.log(`   Preview: Unable to read file content`);
            }

            console.log('');
        });

        console.log('='.repeat(50));
        console.log(`Total migrations to apply: ${migrationFiles.length}`);
        console.log('\nNote: This script only logs the migrations that would be applied.');
        console.log('To actually run the migrations, implement database connection logic.');
    }

    /**
     * Main execution method
     */
    run() {
        this.logMigrations();
    }
}

// Execute the script
const migrationScript = new MigrationScript();
migrationScript.run();

