#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
  constructor() {
    this.migrationsDir = path.join(__dirname, 'migrations');
    this.ensureMigrationsDir();
  }

  /**
   * Ensure the migrations directory exists
   */
  ensureMigrationsDir() {
    if (!fs.existsSync(this.migrationsDir)) {
      console.log(`Creating migrations directory: ${this.migrationsDir}`);
      fs.mkdirSync(this.migrationsDir, { recursive: true });
    }
  }

  /**
   * Get all SQL migration files in the migrations directory
   * @returns {Array} Array of migration file objects with name and path
   */
  getMigrationFiles() {
    try {
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files and sort them alphabetically (which should be chronological)
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort()  // Natural string sort will order files like 001_..., 002_..., etc.
        .map(file => ({
          name: file,
          path: path.join(this.migrationsDir, file)
        }));

      return sqlFiles;
    } catch (error) {
      if (error.code === 'ENOENT') {
        console.log('Migrations directory does not exist.');
        return [];
      }
      throw error;
    }
  }

  /**
   * Log migration files in order without actually applying them
   */
  logMigrations() {
    console.log('=== Database Migration Script ===');
    console.log(`Reading migrations from: ${this.migrationsDir}`);
    console.log('================================\n');

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      console.log('To create a migration:');
      console.log('  1. Add .sql files to the ./migrations/ directory');
      console.log('  2. Name files in chronological order (e.g., 001_create_users.sql, 002_add_email_index.sql)');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file.name}`);
    });

    console.log('\n=== Summary ===');
    console.log(`Total migrations to apply: ${migrationFiles.length}`);
    console.log('Note: This is a dry run - no migrations were actually applied.');
    console.log('To apply migrations, you would need to read and execute the SQL content.');
  }

  /**
   * Optional: Preview SQL content of migrations (without executing)
   */
  previewMigrations() {
    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      return;
    }

    console.log('\n=== Migration Content Preview ===');

    migrationFiles.forEach((file, index) => {
      try {
        const content = fs.readFileSync(file.path, 'utf8');
        const lineCount = content.split('\n').length;
        console.log(`\n${index + 1}. ${file.name} (${lineCount} lines)`);
        console.log('SQL Preview (first 5 lines):');

        const lines = content.split('\n').slice(0, 5);
        lines.forEach(line => {
          if (line.trim()) {
            console.log(`   ${line}`);
          }
        });

        if (content.split('\n').length > 5) {
          console.log('   ...');
        }
      } catch (error) {
        console.log(`\n${index + 1}. ${file.name} - Error reading file: ${error.message}`);
      }
    });
  }
}

// Main execution
function main() {
  const runner = new MigrationRunner();

  // Parse command line arguments
  const args = process.argv.slice(2);
  const preview = args.includes('--preview') || args.includes('-p');

  runner.logMigrations();

  if (preview) {
    runner.previewMigrations();
  }

  console.log('\nUsage:');
  console.log('  node migrate.js              - List migrations in order');
  console.log('  node migrate.js --preview    - List migrations with SQL preview');
  console.log('  node migrate.js -p           - Same as --preview');
}

// Run if called directly
if (require.main === module) {
  main();
}

module.exports = MigrationRunner;

-- Migration: 002_create_posts_table.sql
-- Description: Create posts table with foreign key to users

CREATE TABLE posts (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title VARCHAR(200) NOT NULL,
  content TEXT NOT NULL,
  status VARCHAR(20) DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  published_at TIMESTAMP WITH TIME ZONE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Add indexes for common queries
CREATE INDEX idx_posts_user_id ON posts(user_id);
CREATE INDEX idx_posts_status ON posts(status);
CREATE INDEX idx_posts_published_at ON posts(published_at);

-- Add foreign key constraint explicitly
ALTER TABLE posts ADD CONSTRAINT fk_posts_user_id 
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;

-- Migration: 003_add_user_profile_fields.sql
-- Description: Add additional profile fields to users table

ALTER TABLE users 
ADD COLUMN full_name VARCHAR(100),
ADD COLUMN bio TEXT,
ADD COLUMN avatar_url VARCHAR(255),
ADD COLUMN location VARCHAR(100),
ADD COLUMN website VARCHAR(255);

-- Add index for searching by full name
CREATE INDEX idx_users_full_name ON users(full_name);

-- Add comment to explain the new fields
COMMENT ON COLUMN users.full_name IS 'User''s full name for display purposes';
COMMENT ON COLUMN users.bio IS 'Short biography or description';
COMMENT ON COLUMN users.avatar_url IS 'URL to user''s avatar image';
COMMENT ON COLUMN users.location IS 'User''s location';
COMMENT ON COLUMN users.website IS 'User''s personal website or blog';

-- Migration: 004_create_comments_table.sql
-- Description: Create comments table with relationships to users and posts

CREATE TABLE comments (
  id SERIAL PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  parent_comment_id INTEGER REFERENCES comments(id) ON DELETE CASCADE,
  content TEXT NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Add indexes for performance
CREATE INDEX idx_comments_user_id ON comments(user_id);
CREATE INDEX idx_comments_post_id ON comments(post_id);
CREATE INDEX idx_comments_parent_comment_id ON comments(parent_comment_id);
CREATE INDEX idx_comments_created_at ON comments(created_at);

-- Add foreign key constraints
ALTER TABLE comments ADD CONSTRAINT fk_comments_user_id 
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE;

ALTER TABLE comments ADD CONSTRAINT fk_comments_post_id 
  FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE;

ALTER TABLE comments ADD CONSTRAINT fk_comments_parent_comment_id 
  FOREIGN KEY (parent_comment_id) REFERENCES comments(id) ON DELETE CASCADE;

-- Add check constraint to prevent self-referencing at top level
ALTER TABLE comments ADD CONSTRAINT chk_comments_no_self_parent 
  CHECK (parent_comment_id IS NULL OR parent_comment_id != id);

