/**
 * Load DATABASE_URL from environment file
 */
loadDatabaseUrl() {
  // First try to get from process.env (dotenv might have loaded it)
  if (process.env.DATABASE_URL) {
    this.databaseUrl = process.env.DATABASE_URL;
    console.log(`Loaded DATABASE_URL from environment variables`);
    return;
  }

  // Try to load from .env file
  const envFilePath = this.envFile;
  try {
    if (fs.existsSync(envFilePath)) {
      const envContent = fs.readFileSync(envFilePath, 'utf8');
      const lines = envContent.split('\n');

      for (const line of lines) {
        const trimmedLine = line.trim();

        // Skip comments and empty lines
        if (!trimmedLine || trimmedLine.startsWith('#')) {
          continue;
        }

        // Parse KEY=VALUE
        const equalsIndex = trimmedLine.indexOf('=');
        if (equalsIndex !== -1) {
          const key = trimmedLine.substring(0, equalsIndex).trim();
          const value = trimmedLine.substring(equalsIndex + 1).trim();

          if (key === 'DATABASE_URL') {
            this.databaseUrl = value;
            console.log(`Loaded DATABASE_URL from ${envFilePath}`);
            break;
          }
        }
      }
    }
  } catch (error) {
    console.log(`Warning: Could not read ${envFilePath}: ${error.message}`);
  }

  if (!this.databaseUrl) {
    console.log(`Warning: DATABASE_URL not found in ${envFilePath} or environment variables`);
  }
}

/**
 * Log connection success message (simulated connection)
 */
logConnectionSuccess() {
  console.log('\n=== Database Connection ===');

  if (this.databaseUrl) {
    // Parse the URL to extract information (for logging purposes only)
    try {
      const url = new URL(this.databaseUrl);
      const protocol = url.protocol.replace(':', '');
      const hostname = url.hostname;
      const port = url.port || (protocol === 'postgres' ? '5432' : 'unknown');
      const database = url.pathname.substring(1) || 'default';
      const username = url.username || 'anonymous';

      console.log(`✓ Successfully loaded connection string from ${this.envFile}`);
      console.log(`  Protocol: ${protocol}`);
      console.log(`  Host: ${hostname}:${port}`);
      console.log(`  Database: ${database}`);
      console.log(`  Username: ${username}`);
      console.log(`  Connection would be established to: ${protocol}://${hostname}:${port}/${database}`);

      // Show a masked version of the URL for security
      const maskedUrl = this.maskConnectionString(this.databaseUrl);
      console.log(`  Connection string: ${maskedUrl}`);

    } catch (error) {
      console.log(`✓ Successfully loaded connection string from ${this.envFile}`);
      console.log(`  Raw connection string: ${this.maskConnectionString(this.databaseUrl)}`);
    }
  } else {
    console.log('⚠ No DATABASE_URL found. Running in dry-run mode only.');
    console.log('  To enable database operations, add DATABASE_URL to:');
    console.log(`    1. ${this.envFile} file`);
    console.log('    2. Or set as environment variable');
  }
  console.log('===========================\n');
}

/**
 * Mask sensitive parts of connection string for logging
 */
maskConnectionString(connectionString) {
  if (!connectionString) return 'null';

  // Simple masking: replace password with ****
  try {
    const url = new URL(connectionString);
    if (url.password) {
      return connectionString.replace(
        `:${url.password}@`, 
        `:****@`
      );
    }
  } catch (error) {
    // If parsing fails, do a simple replace
    const atIndex = connectionString.indexOf('@');
    if (atIndex !== -1) {
      const beforeAt = connectionString.substring(0, atIndex);
      const colonIndex = beforeAt.lastIndexOf(':');
      if (colonIndex !== -1) {
        return connectionString.substring(0, colonIndex + 1) + '****' + 
               connectionString.substring(atIndex);
      }
    }
  }

  return connectionString;
}

/**
 * Ensure the migrations directory exists
 */
ensureMigrationsDir() {
  if (!fs.existsSync(this.migrationsDir)) {
    console.log(`Creating migrations directory: ${this.migrationsDir}`);
    fs.mkdirSync(this.migrationsDir, { recursive: true });
  }
}

