      // Filter for SQL files and sort them alphabetically (which should be chronological)
      const sqlFiles = files
        .filter(file => file.endsWith('.sql'))
        .sort()  // Natural string sort will order files like 001_..., 002_..., etc.
        .map(file => ({
          name: file,
          path: path.join(this.migrationsDir, file)
        }));

      return sqlFiles;
    } catch (error) {
      if (error.code === 'ENOENT') {
        console.log('Migrations directory does not exist.');
        return [];
      }
      throw error;
    }
  }

  /**
   * Log migration files in order without actually applying them
   */
  logMigrations() {
    console.log('=== Database Migration Script ===');
    console.log(`Reading migrations from: ${this.migrationsDir}`);
    console.log(`Environment file: ${this.envFile}`);
    console.log('================================\n');

    // Log connection status
    this.logConnectionSuccess();

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No SQL migration files found.');
      console.log('To create a migration:');
      console.log('  1. Add .sql files to the ./migrations/ directory');
      console.log('  2. Name files in chronological order (e.g., 001_create_users.sql, 002_add_email_index.sql)');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file.name}`);
    });

    console.log('\n=== Summary ===');
    console.log(`Total migrations to apply: ${migrationFiles.length}`);

    if (this.databaseUrl) {
      console.log(`Status: Ready to apply migrations to database`);
      console.log(`Note: This is a simulation - no migrations would be applied without additional logic`);
    } else {
      console.log(`Status: Dry-run only (no DATABASE_URL configured)`);
      console.log(`Note: No database operations would be performed`);
    }
  }

  /**
   * Optional: Preview SQL content of migrations (without executing)
   */
  previewMigrations() {
    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      return;
    }

    console.log('\n=== Migration Content Preview ===');

    migrationFiles.forEach((file, index) => {
