#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 * 
 * Usage: node migrate.js
 */

function readMigrations() {
    const migrationsDir = './migrations';

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory "${migrationsDir}" does not exist.`);
        console.log(`Creating "${migrationsDir}" directory...`);
        fs.mkdirSync(migrationsDir, { recursive: true });
        console.log(`Directory created. Please add SQL migration files to "${migrationsDir}/"`);
        return [];
    }

    try {
        // Read all files from the migrations directory
        const files = fs.readdirSync(migrationsDir);

        // Filter for SQL files
        const sqlFiles = files
            .filter(file => file.endsWith('.sql'))
            .map(file => ({
                name: file,
                path: path.join(migrationsDir, file)
            }));

        // Sort files alphabetically (which gives us chronological order if named properly)
        sqlFiles.sort((a, b) => a.name.localeCompare(b.name, undefined, { numeric: true }));

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        return [];
    }
}

function logMigrations(migrations) {
    console.log('Database Migration Script');
    console.log('=========================');
    console.log(`Found ${migrations.length} SQL migration file(s) in ./migrations/\n`);

    if (migrations.length === 0) {
        console.log('No migration files to apply.');
        console.log('Add SQL files to the ./migrations/ directory to see them listed here.');
        return;
    }

    console.log('Migration files that would be applied (in order):\n');

    migrations.forEach((migration, index) => {
        console.log(`${index + 1}. ${migration.name}`);

        // Optional: Read and show the first few lines of each SQL file
        try {
            const content = fs.readFileSync(migration.path, 'utf8');
            const previewLines = content.split('\n').slice(0, 3).join('\n');
            const truncatedPreview = previewLines.length > 100 
                ? previewLines.substring(0, 100) + '...' 
                : previewLines;

            if (truncatedPreview.trim()) {
                console.log(`   Preview: ${truncatedPreview}`);
            }
        } catch (error) {
            console.log(`   (Could not read file: ${error.message})`);
        }

        console.log(); // Empty line between migrations
    });

    console.log(`\nThese ${migrations.length} migration file(s) would be applied in the order shown above.`);
    console.log('\nNote: This script only logs the files - actual database execution would require additional implementation.');
    console.log('To execute migrations, you would need to:');
    console.log('1. Establish a database connection');
    console.log('2. Read each SQL file content');
    console.log('3. Execute the SQL statements in a transaction');
    console.log('4. Track which migrations have been applied (migration table)');
}

function main() {
    console.log('Starting migration script...\n');

    const migrations = readMigrations();
    logMigrations(migrations);
}

// Run the main function
if (require.main === module) {
    main();
}

module.exports = { readMigrations, logMigrations };

