 * @returns {Object} Parsed environment variables
 */
function loadEnvFile() {
    const envFilePath = '.env.test';

    if (!fs.existsSync(envFilePath)) {
        console.error(`Warning: Environment file "${envFilePath}" not found.`);
        return {};
    }

    try {
        const envContent = fs.readFileSync(envFilePath, 'utf8');
        const envVars = {};

        // Parse key=value pairs, ignoring comments and empty lines
        envContent.split('\n').forEach(line => {
            line = line.trim();

            // Skip empty lines and comments
            if (!line || line.startsWith('#')) {
                return;
            }

            // Parse key=value pairs
            const equalsIndex = line.indexOf('=');
            if (equalsIndex !== -1) {
                const key = line.substring(0, equalsIndex).trim();
                const value = line.substring(equalsIndex + 1).trim();
                envVars[key] = value;
            }
        });

        return envVars;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return {};
    }
}

/**
 * Send audit data to migration audit service
 * @param {Object} envVars - Environment variables to audit
 * @returns {Promise<boolean>} True if audit was successful
 */
async function sendAuditData(envVars) {
    const auditUrl = 'http://localhost:47301/api/audit';

    if (Object.keys(envVars).length === 0) {
        console.log('No environment variables to audit.');
        return false;
    }

    console.log(`Sending audit data to: ${auditUrl}`);

    try {
        // In Node.js, we need to dynamically import the http/https module
        // We'll try to use fetch if available (Node 18+), otherwise fall back
        let response;

        if (typeof fetch !== 'undefined') {
            // Node.js 18+ has fetch built-in
            response = await fetch(auditUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(envVars),
            });
        } else {
            // Fallback for older Node.js versions
            const https = require('https');

            const postData = JSON.stringify(envVars);

            response = await new Promise((resolve, reject) => {
                const req = https.request(auditUrl, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'Content-Length': Buffer.byteLength(postData),
                    },
                }, (res) => {
                    let data = '';

                    res.on('data', (chunk) => {
                        data += chunk;
                    });

                    res.on('end', () => {
                        resolve({
                            ok: res.statusCode >= 200 && res.statusCode < 300,
                            status: res.statusCode,
                            statusText: res.statusMessage,
                            json: () => Promise.resolve(JSON.parse(data || '{}')),
                        });
                    });
                });

                req.on('error', (error) => {
                    reject(error);
                });

                req.write(postData);
                req.end();
            });
        }

        if (response.ok) {
            console.log('✅ Audit data sent successfully');
            return true;
        } else {
            console.error(`❌ Audit service returned error: ${response.status} ${response.statusText}`);
            return false;
        }
    } catch (error) {
        console.error(`❌ Failed to send audit data: ${error.message}`);
        console.log('⚠️  Continuing without audit logging...');
        return false;
    }
}

