#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL migration files from the ./migrations/ directory
 * and logs each filename in the order they would be applied.
 */

class MigrationRunner {
  constructor(migrationsDir = './migrations') {
    this.migrationsDir = migrationsDir;
  }

  /**
   * Get all migration files sorted in order
   * @returns {Array} Array of sorted migration file names
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Migrations directory '${this.migrationsDir}' does not exist.`);
        process.exit(1);
      }

      // Read all files from migrations directory
      const files = fs.readdirSync(this.migrationsDir);

      // Filter for SQL files only
      const sqlFiles = files.filter(file => file.endsWith('.sql'));

      // Sort files by name to ensure correct order
      // This relies on the naming convention (e.g., 001_, 002_, etc.)
      const sortedFiles = sqlFiles.sort((a, b) => {
        return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
      });

      return sortedFiles;
    } catch (error) {
      console.error(`Error reading migrations directory: ${error.message}`);
      process.exit(1);
    }
  }

  /**
   * Log migration files that would be applied
   */
  logMigrations() {
    console.log('📋 Database Migration Script');
    console.log('==============================');
    console.log(`Reading migration files from: ${this.migrationsDir}\n`);

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migration files found.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
      const filePath = path.join(this.migrationsDir, file);
      const migrationNumber = (index + 1).toString().padStart(3, '0');

      console.log(`${migrationNumber}. ${file}`);

      // Optional: Show first line of SQL content as preview
      try {
        const content = fs.readFileSync(filePath, 'utf8');
        const firstLine = content.split('\n')[0].trim();
        if (firstLine) {
          console.log(`   ↳ ${firstLine}`);
        }
      } catch (error) {
        console.log(`   ↳ [Error reading file: ${error.message}]`);
      }

      console.log(); // Empty line for readability
    });

    console.log('==============================');
    console.log('Migration files logged successfully.');
    console.log('To actually apply migrations, implement database connection logic.');
  }

  /**
   * Main execution method
   */
  run() {
    this.logMigrations();
  }
}

// Command line interface
function parseArguments() {
  const args = process.argv.slice(2);
  const options = {
    dir: './migrations'
  };

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--dir' && args[i + 1]) {
      options.dir = args[i + 1];
      i++;
    } else if (args[i] === '--help' || args[i] === '-h') {
      printHelp();
      process.exit(0);
    }
  }

  return options;
}

function printHelp() {
  console.log(`
Database Migration Script
Usage: node migrate.js [options]

Options:
  --dir <path>    Specify migrations directory (default: ./migrations)
  --help, -h      Show this help message

Description:
  This script reads SQL migration files from the specified directory
  and logs each filename in the order they would be applied.
  `);
}

// Execute script
if (require.main === module) {
  const options = parseArguments();
  const runner = new MigrationRunner(options.dir);
  runner.run();
}

// Export for testing purposes
module.exports = MigrationRunner;

