const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL migration files from the ./migrations/ directory
 * and logs each filename in the order they would be applied.
 */

class MigrationRunner {
  constructor(migrationsDir = './migrations', envFile = '.env.test') {
    this.migrationsDir = migrationsDir;
    this.envFile = envFile;
    this.databaseUrl = null;
  }

  /**
   * Load environment variables from .env.test file
   */
  loadEnvironmentVariables() {
    try {
      if (!fs.existsSync(this.envFile)) {
        console.warn(`⚠️  Environment file '${this.envFile}' not found.`);
        return false;
      }

      const envContent = fs.readFileSync(this.envFile, 'utf8');
      const lines = envContent.split('\n');

      for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (!trimmedLine || trimmedLine.startsWith('#')) {
          continue;
        }

        // Parse key=value pairs
        const equalsIndex = trimmedLine.indexOf('=');
        if (equalsIndex !== -1) {
          const key = trimmedLine.substring(0, equalsIndex).trim();
          const value = trimmedLine.substring(equalsIndex + 1).trim();

          if (key === 'DATABASE_URL') {
            this.databaseUrl = value;
            break; // Found what we need
          }
        }
      }

      return this.databaseUrl !== null;
    } catch (error) {
      console.error(`Error reading environment file: ${error.message}`);
      return false;
    }
  }

  /**
   * Log database connection information
   */
  logConnectionInfo() {
    console.log('🔌 Database Connection Info');
    console.log('==============================');

    if (this.databaseUrl) {
      // Parse the database URL to extract components (safely)
      try {
        const url = new URL(this.databaseUrl);
        const protocol = url.protocol.replace(':', '');
        const hostname = url.hostname;
        const port = url.port || (protocol === 'postgres' ? '5432' : '3306');
        const database = url.pathname.substring(1); // Remove leading slash
        const username = url.username || 'unknown';

        console.log(`✅ Successfully loaded DATABASE_URL from ${this.envFile}`);
        console.log(`📡 Protocol: ${protocol}`);
        console.log(`👤 Username: ${username}`);
        console.log(`🌐 Host: ${hostname}:${port}`);
        console.log(`🗄️  Database: ${database}`);

        // Mask password for security
        const maskedUrl = this.databaseUrl.replace(/:[^:@]*@/, ':***@');
        console.log(`🔗 Connection URL: ${maskedUrl}`);
      } catch (error) {
        console.log(`✅ DATABASE_URL loaded: ${this.databaseUrl.substring(0, 50)}...`);
        console.log(`   (URL parsing error: ${error.message})`);
      }
    } else {
      console.log(`❌ DATABASE_URL not found in ${this.envFile}`);
      console.log('⚠️  Running in dry-run mode without database connection');
    }

    console.log('==============================\n');
  }

