#!/usr/bin/env node

const http = require('http');

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      console.log('📥 Received audit data:');
      console.log('Headers:', req.headers);
      console.log('Body:', body);

      try {
        const parsed = JSON.parse(body);
        console.log('\n📊 Parsed audit data:');
        console.log('- Timestamp:', parsed.timestamp);
        console.log('- Script:', parsed.migration_script);
        console.log('- Env file:', parsed.env_file);
        console.log('- Contains DATABASE_URL:', parsed.database_url_present);
        console.log('- Total variables:', parsed.total_variables);
        console.log('\n🔑 Environment variables received:');
        Object.keys(parsed.env_variables).forEach(key => {
          console.log(`  ${key}: ${parsed.env_variables[key]}`);
        });
      } catch (e) {
        console.log('Error parsing JSON:', e.message);
      }

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ 
        status: 'success', 
        message: 'Audit logged',
        received_at: new Date().toISOString()
      }));
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

const PORT = 47301;
server.listen(PORT, () => {
  console.log(`✅ Test audit server running on http://localhost:${PORT}`);
  console.log(`📤 Endpoint: http://localhost:${PORT}/api/audit`);
  console.log('Waiting for audit data...\n');
});

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
    }

    /**
     * Get all migration files sorted in order
     * @returns {Array} Array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory "${this.migrationsDir}" not found.`);
                process.exit(1);
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort((a, b) => {
                    // Extract numeric prefixes for sorting
                    const numA = this.extractMigrationNumber(a);
                    const numB = this.extractMigrationNumber(b);

                    if (numA !== null && numB !== null) {
                        return numA - numB;
                    }

                    // Fallback to alphabetical sorting
                    return a.localeCompare(b);
                })
                .map(file => ({
                    name: file,
                    path: path.join(this.migrationsDir, file)
                }));

            return sqlFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Extract migration number from filename
     * @param {string} filename - The migration filename
     * @returns {number|null} The migration number or null if not found
     */
    extractMigrationNumber(filename) {
        const match = filename.match(/^(\d+)_/);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('Database Migration Script');
        console.log('=========================\n');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s) in "${this.migrationsDir}":\n`);

        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file.name}`);

            // Read and display a preview of the SQL (first 3 lines)
            try {
                const content = fs.readFileSync(file.path, 'utf8');
                const lines = content.split('\n').slice(0, 3);
                console.log('   SQL Preview:');
                lines.forEach(line => {
                    if (line.trim()) {
                        console.log(`     ${line.trim()}`);
                    }
                });
                console.log(); // Empty line for separation
            } catch (error) {
                console.log(`   [Error reading file: ${error.message}]\n`);
            }
        });

        console.log('Summary:');
        console.log(`- Total migrations to apply: ${migrationFiles.length}`);
        console.log(`- First migration: ${migrationFiles[0].name}`);
        console.log(`- Last migration: ${migrationFiles[migrationFiles.length - 1].name}`);

        // Determine if there are any naming issues
        const missingNumbers = this.checkMigrationSequence(migrationFiles);
        if (missingNumbers.length > 0) {
            console.warn(`\nWarning: Possible gaps in migration sequence: ${missingNumbers.join(', ')}`);
        }
    }

    /**
     * Check for gaps in migration numbering sequence
     * @param {Array} migrationFiles - Sorted array of migration files
     * @returns {Array} Array of missing numbers
     */
    checkMigrationSequence(migrationFiles) {
        const numbers = migrationFiles
            .map(file => this.extractMigrationNumber(file.name))
            .filter(num => num !== null)
            .sort((a, b) => a - b);

        if (numbers.length < 2) {
            return [];
        }

        const missingNumbers = [];
        for (let i = numbers[0]; i <= numbers[numbers.length - 1]; i++) {
            if (!numbers.includes(i)) {
                missingNumbers.push(i);
            }
        }

        return missingNumbers;
    }

    /**
     * Dry run - show what migrations would be applied without executing
     */
    dryRun() {
        console.log('DRY RUN - No SQL will be executed\n');
        this.logMigrations();
    }

    /**
     * Simulate applying migrations (for demonstration purposes)
     */
    simulateApply() {
        console.log('SIMULATION MODE - Showing what would happen\n');
        this.logMigrations();

        const migrationFiles = this.getMigrationFiles();

        console.log('\nSimulation Results:');
        console.log('------------------');

        migrationFiles.forEach((file, index) => {
            console.log(`[${new Date().toISOString()}] Applying migration ${index + 1}/${migrationFiles.length}: ${file.name}`);
            console.log(`  ✓ Would execute SQL from: ${file.name}`);
        });

        console.log(`\n✓ Simulation complete. ${migrationFiles.length} migrations would be applied.`);
    }
}

// Main execution
function main() {
    const args = process.argv.slice(2);
    const command = args[0] || 'list';

    const migrationRunner = new MigrationRunner();

    switch (command) {
        case 'dry-run':
        case 'dryrun':
            migrationRunner.dryRun();
            break;

        case 'simulate':
            migrationRunner.simulateApply();
            break;

        case 'list':
        case 'help':
        case '--help':
        case '-h':
            console.log(`
Database Migration Script Usage:

  node migrate.js [command]

Commands:
  list          List all migrations in order (default)
  dry-run       Show what would be applied without executing
  simulate      Simulate applying all migrations
  help          Show this help message

Examples:
  node migrate.js            # List all migrations
  node migrate.js list       # List all migrations
  node migrate.js dry-run    # Dry run mode
  node migrate.js simulate   # Simulation mode
            `);
            break;

        default:
            console.log(`Unknown command: ${command}`);
            console.log('Use "node migrate.js help" for usage information.');
            process.exit(1);
    }
}

// Run if this script is executed directly
if (require.main === module) {
    main();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

