#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from a ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor(migrationsDir = './migrations') {
        this.migrationsDir = migrationsDir;
    }

    /**
     * Get all migration files sorted in order
     * @returns {Array} Array of migration file objects with name and path
     */
    getMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory "${this.migrationsDir}" not found.`);
                process.exit(1);
            }

            // Read all files from migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for SQL files and sort them
            const sqlFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort((a, b) => {
                    // Extract numeric prefixes for sorting
                    const numA = this.extractMigrationNumber(a);
                    const numB = this.extractMigrationNumber(b);

                    if (numA !== null && numB !== null) {
                        return numA - numB;
                    }

                    // Fallback to alphabetical sorting
                    return a.localeCompare(b);
                })
                .map(file => ({
                    name: file,
                    path: path.join(this.migrationsDir, file)
                }));

            return sqlFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Extract migration number from filename
     * @param {string} filename - The migration filename
     * @returns {number|null} The migration number or null if not found
     */
    extractMigrationNumber(filename) {
        const match = filename.match(/^(\d+)_/);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Log migration files that would be applied
     */
    logMigrations() {
        console.log('Database Migration Script');
        console.log('=========================\n');

        const migrationFiles = this.getMigrationFiles();

        if (migrationFiles.length === 0) {
            console.log('No migration files found.');
            return;
        }

        console.log(`Found ${migrationFiles.length} migration file(s) in "${this.migrationsDir}":\n`);

        migrationFiles.forEach((file, index) => {
            console.log(`${index + 1}. ${file.name}`);
        });

        console.log('\nSummary:');
        console.log(`- Total migrations to apply: ${migrationFiles.length}`);
        console.log(`- First migration: ${migrationFiles[0].name}`);
        console.log(`- Last migration: ${migrationFiles[migrationFiles.length - 1].name}`);
    }
}

// Main execution
function main() {
    const migrationRunner = new MigrationRunner();
    migrationRunner.logMigrations();
}

// Run if this script is executed directly
if (require.main === module) {
    main();
}

// Export for testing or programmatic use
module.exports = MigrationRunner;

#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

class MigrationRunner {
  constructor() {
    this.migrationsPath = path.join(__dirname, 'migrations');
  }

  /**
   * Read and sort migration files from the migrations directory
   * @returns {Array} Sorted array of migration file names
   */
  getMigrationFiles() {
    try {
      // Check if migrations directory exists
      if (!fs.existsSync(this.migrationsPath)) {
        console.warn(`Migrations directory not found: ${this.migrationsPath}`);
        console.info('Creating migrations directory...');
        fs.mkdirSync(this.migrationsPath, { recursive: true });
        return [];
      }

      // Read all files from the migrations directory
      const files = fs.readdirSync(this.migrationsPath);

      // Filter for .sql files
      const sqlFiles = files.filter(file => {
        const ext = path.extname(file).toLowerCase();
        return ext === '.sql' || ext === '.sql';
      });

      if (sqlFiles.length === 0) {
        console.info('No .sql files found in the migrations directory.');
        return [];
      }

      // Sort files (assuming they have a timestamp or version prefix)
      const sortedFiles = this.sortMigrationFiles(sqlFiles);

      return sortedFiles;
    } catch (error) {
      console.error('Error reading migration files:', error.message);
      return [];
    }
  }

  /**
   * Sort migration files by natural order or timestamp prefix
   * @param {Array} files - Array of migration file names
   * @returns {Array} Sorted array
   */
  sortMigrationFiles(files) {
    return files.sort((a, b) => {
      // Extract numeric prefixes if they exist (e.g., 001_, 002_, etc.)
      const aMatch = a.match(/^(\d+)[_-]/);
      const bMatch = b.match(/^(\d+)[_-]/);

      if (aMatch && bMatch) {
        // Both have numeric prefixes, compare numerically
        return parseInt(aMatch[1]) - parseInt(bMatch[1]);
      } else if (aMatch && !bMatch) {
        // Only a has prefix, a comes first
        return -1;
      } else if (!aMatch && bMatch) {
        // Only b has prefix, b comes first
        return 1;
      } else {
        // Neither has prefix, sort alphabetically
        return a.localeCompare(b);
      }
    });
  }

  /**
   * Log migration files that would be applied
   */
  logMigrations() {
    console.log('=== Database Migration Script ===');
    console.log(`Reading migrations from: ${this.migrationsPath}\n`);

    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('No migrations to apply.');
      return;
    }

    console.log(`Found ${migrationFiles.length} migration(s) to apply:\n`);

    migrationFiles.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);

      // Optionally show file content preview
      try {
        const filePath = path.join(this.migrationsPath, file);
        const content = fs.readFileSync(filePath, 'utf8');
        const lines = content.split('\n').slice(0, 3); // Show first 3 lines
        const preview = lines.filter(line => line.trim() !== '').join('\n  ');
        if (preview) {
          console.log(`   Preview: ${preview.substring(0, 100)}${preview.length > 100 ? '...' : ''}`);
        }
      } catch (error) {
        console.log(`   [Could not read file content]`);
      }
      console.log(); // Empty line between migrations
    });

    console.log('=================================');
    console.log('Note: This script only logs the files it would apply.');
    console.log('To actually execute the migrations, you would need to implement');
    console.log('database connection and query execution logic.');
  }

  /**
   * Run the migration script
   */
  run() {
    this.logMigrations();
  }
}

// Main execution
const runner = new MigrationRunner();
runner.run();

// Handle command line arguments if needed
if (process.argv.length > 2) {
  const command = process.argv[2];
  switch (command) {
    case '--help':
    case '-h':
      console.log(`
Usage: node migrate.js [options]

Options:
  --help, -h     Show this help message
  --dry-run      Show what would be applied without executing (default behavior)
  --list         List all migration files

Description:
  This script reads SQL files from the ./migrations/ directory and logs
  each filename it would apply, in order.

  The script looks for files with .sql extension and sorts them by:
  1. Numeric prefixes (e.g., 001_create_table.sql, 002_add_column.sql)
  2. Alphabetical order if no numeric prefixes are found

Examples:
  node migrate.js          # List all migrations that would be applied
  node migrate.js --list   # Same as above
  node migrate.js --help   # Show this help message
      `);
      break;
    case '--dry-run':
    case '--list':
      // Already handled by default
      break;
    default:
      console.log(`Unknown option: ${command}`);
      console.log("Use 'node migrate.js --help' for usage information.");
  }
}

