#!/usr/bin/env node

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

class MigrationRunner {
  constructor() {
    this.migrationsPath = path.join(__dirname, 'migrations');
    this.envFilePath = path.join(__dirname, '.env.test');
    this.databaseUrl = null;
  }

  /**
   * Read DATABASE_URL from .env.test file
   * @returns {string|null} DATABASE_URL value or null if not found
   */
  readDatabaseUrl() {
    try {
      // Check if .env.test exists
      if (!fs.existsSync(this.envFilePath)) {
        console.warn(`Environment file not found: ${this.envFilePath}`);
        return null;
      }

      // Read and parse the .env.test file
      const envContent = fs.readFileSync(this.envFilePath, 'utf8');

      // Parse DATABASE_URL from the file
      const lines = envContent.split('\n');
      let dbUrl = null;

      for (const line of lines) {
        // Skip comments and empty lines
        const trimmed = line.trim();
        if (!trimmed || trimmed.startsWith('#')) continue;

        // Look for DATABASE_URL line
        if (trimmed.startsWith('DATABASE_URL=')) {
          dbUrl = trimmed.substring('DATABASE_URL='.length).trim();
          // Remove quotes if present
          dbUrl = dbUrl.replace(/^['"]|['"]$/g, '');
          break;
        }
      }

      return dbUrl;
    } catch (error) {
      console.error(`Error reading ${this.envFilePath}:`, error.message);
      return null;
    }
  }

  /**
   * Parse database URL to extract connection details
   * @param {string} dbUrl - Database connection string
   * @returns {object} Parsed connection details
   */
  parseDatabaseUrl(dbUrl) {
    if (!dbUrl) return null;

    try {
      // Parse the PostgreSQL URL format: postgres://user:password@host:port/database
      const urlPattern = /^(postgres(?:ql)?):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
      const match = dbUrl.match(urlPattern);

      if (match) {
        return {
          protocol: match[1],
          username: match[2],
          password: '***', // Mask password for security
          host: match[3],
          port: match[4],
          database: match[5],
          fullUrl: dbUrl
        };
      }

      // Try a more generic pattern
      const genericPattern = /^([^:]+):\/\/([^@]+)@([^/]+)\/(.+)$/;
      const genericMatch = dbUrl.match(genericPattern);

      if (genericMatch) {
        return {
          protocol: genericMatch[1],
          credentials: genericMatch[2],
          host: genericMatch[3],
          database: genericMatch[4],
          fullUrl: dbUrl
        };
      }

      // If no pattern matches, return the URL as-is
      return {
        fullUrl: dbUrl,
        raw: dbUrl
      };
    } catch (error) {
      console.error('Error parsing DATABASE_URL:', error.message);
      return {
        fullUrl: dbUrl,
        raw: dbUrl,
        error: 'Failed to parse URL'
      };
    }
  }

  /**
   * Log connection success message
   * @param {object} connectionDetails - Parsed connection details
   */
  logConnectionSuccess(connectionDetails) {
    console.log('=== Database Connection ===');

    if (!connectionDetails) {
      console.log('❌ No DATABASE_URL found in .env.test');
      console.log('');
      return;
    }

    console.log('✅ Successfully read DATABASE_URL from .env.test');

    // Display parsed connection details
    if (connectionDetails.protocol && connectionDetails.username && connectionDetails.host) {
      console.log(`   Database: ${connectionDetails.database}`);
      console.log(`   Type: ${connectionDetails.protocol}`);
      console.log(`   Host: ${connectionDetails.host}:${connectionDetails.port}`);
      console.log(`   User: ${connectionDetails.username}`);
      console.log(`   Password: ${connectionDetails.password}`);
    } else if (connectionDetails.fullUrl) {
      // Display a sanitized version of the URL (mask password)
      const sanitizedUrl = connectionDetails.fullUrl.replace(/:\/\/[^:]+:[^@]+@/, '://***:***@');
      console.log(`   URL: ${sanitizedUrl}`);
    }

    console.log('');
  }

