/**
 * Parse database URL to extract connection details
 * @param {string} dbUrl - Database connection string
 * @returns {object} Parsed connection details
 */
parseDatabaseUrl(dbUrl) {
  if (!dbUrl) return null;

  try {
    // Use the URL API for more robust parsing
    const url = new URL(dbUrl);
    const protocol = url.protocol.replace(':', '');
    const hostname = url.hostname;
    const port = url.port || (protocol === 'postgres' || protocol === 'postgresql' ? '5432' : '');
    const database = url.pathname.replace('/', '');

    // Extract username and password
    let username = '';
    let password = '***';

    if (url.username) {
      username = url.username;
    }
    if (url.password) {
      // Password is masked for security
      password = '***';
    }

    return {
      protocol,
      username,
      password,
      host: hostname,
      port,
      database,
      fullUrl: dbUrl
    };
  } catch (error) {
    // Fallback to regex parsing if URL parsing fails
    console.warn('URL parsing failed, trying regex fallback:', error.message);

    try {
      // Try regex pattern for postgres://user:password@host:port/database
      const regex = /^(postgres(?:ql)?):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
      const match = dbUrl.match(regex);

      if (match) {
        return {
          protocol: match[1],
          username: match[2],
          password: '***',
          host: match[4],
          port: match[5],
          database: match[6],
          fullUrl: dbUrl
        };
      }

      // Generic pattern for other database URLs
      const genericRegex = /^([a-z]+):\/\/([^@]+)@([^/]+)\/(.+)$/;
      const genericMatch = dbUrl.match(genericRegex);

      if (genericMatch) {
        return {
          protocol: genericMatch[1],
          credentials: '***',
          host: genericMatch[3],
          database: genericMatch[4],
          fullUrl: dbUrl
        };
      }

      // If no pattern matches, return the URL as-is
      return {
        fullUrl: dbUrl,
        raw: dbUrl,
        protocol: 'unknown'
      };
    } catch (regexError) {
      console.error('Error parsing DATABASE_URL:', regexError.message);
      return {
        fullUrl: dbUrl,
        raw: dbUrl,
        error: 'Failed to parse URL'
      };
    }
  }
}

