#!/usr/bin/env node

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order
 */

const fs = require('fs');
const path = require('path');

class MigrationScript {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        this.migrations = [];
    }

    /**
     * Read all migration files from the migrations directory
     * @returns {Array} Array of migration file names
     */
    readMigrationFiles() {
        try {
            // Check if migrations directory exists
            if (!fs.existsSync(this.migrationsDir)) {
                console.error(`Error: Migrations directory not found at ${this.migrationsDir}`);
                process.exit(1);
            }

            // Read all files in migrations directory
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files
            const sqlFiles = files.filter(file => file.endsWith('.sql'));

            if (sqlFiles.length === 0) {
                console.log('No SQL migration files found in migrations directory.');
            }

            return sqlFiles;
        } catch (error) {
            console.error('Error reading migration files:', error.message);
            process.exit(1);
        }
    }

    /**
     * Sort migration files by their numerical prefix
     * @param {Array} files - Array of migration file names
     * @returns {Array} Sorted array of file names
     */
    sortMigrationFiles(files) {
        // Extract numerical prefix from filename (e.g., "001_", "010_", etc.)
        const fileInfo = files.map(file => {
            // Match numbers at the beginning of filename
            const match = file.match(/^(\d+)_/);
            const number = match ? parseInt(match[1], 10) : 0;
            return { file, number };
        });

        // Sort by numerical prefix
        fileInfo.sort((a, b) => a.number - b.number);

        // Return sorted file names
        return fileInfo.map(info => info.file);
    }

    /**
     * Log migration files in order
     */
    logMigrations() {
        console.log('Database Migration Script');
        console.log('=========================');
        console.log(`Reading migration files from: ${this.migrationsDir}\n`);

        const migrationFiles = this.readMigrationFiles();
        const sortedMigrations = this.sortMigrationFiles(migrationFiles);

        if (sortedMigrations.length === 0) {
            console.log('No migration files to process.');
            return;
        }

        console.log(`Found ${sortedMigrations.length} migration file(s):\n`);

        // Log each migration file in order
        sortedMigrations.forEach((file, index) => {
            const filePath = path.join(this.migrationsDir, file);
            console.log(`${index + 1}. ${file}`);

            // Optional: Read and log first line of SQL file as description
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                const firstLine = content.split('\n')[0].trim();

                // Remove SQL comment markers if present
                const description = firstLine.startsWith('--') 
                    ? firstLine.substring(2).trim()
                    : firstLine;

                if (description) {
                    console.log(`   ${description}`);
                }
            } catch (error) {
                console.log(`   (Could not read file contents)`);
            }

            console.log(); // Empty line for readability
        });

        console.log('\nMigration files would be applied in the order shown above.');
        console.log('To actually apply migrations, you would need to:');
        console.log('1. Read each SQL file');
        console.log('2. Execute the SQL against your database');
        console.log('3. Track which migrations have been applied');
    }

    /**
     * Main method to run the script
     */
    run() {
        this.logMigrations();
    }
}

// Run the script if called directly
if (require.main === module) {
    const migrationScript = new MigrationScript();
    migrationScript.run();
}

module.exports = MigrationScript;

