    const fileInfo = files.map(file => {
        // Match numbers at the beginning of filename
        const match = file.match(/^(\d+)_/);
        if (match) {
            return { file, number: parseInt(match[1], 10), hasPrefix: true };
        } else {
            // Files without numerical prefix come last
            return { file, number: Infinity, hasPrefix: false };
        }
    });

    // Sort: first by whether they have prefix, then by number
    fileInfo.sort((a, b) => {
        if (a.hasPrefix && b.hasPrefix) {
            return a.number - b.number;
        } else if (a.hasPrefix && !b.hasPrefix) {
            return -1; // Files with prefix come first
        } else if (!a.hasPrefix && b.hasPrefix) {
            return 1; // Files without prefix come last
        } else {
            // Both don't have prefix, sort alphabetically
            return a.file.localeCompare(b.file);
        }
    });

    // Return sorted file names
    return fileInfo.map(info => info.file);
}

