function readAndLogMigrations() {
    const migrationsDir = path.join(__dirname, 'migrations');

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory not found at ${migrationsDir}`);
        process.exit(1);
    }

    // Read all files in migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for .sql files
    const sqlFiles = files.filter(file => file.endsWith('.sql'));

    if (sqlFiles.length === 0) {
        console.log('No SQL migration files found in migrations directory.');
        return;
    }

    // Sort files by their numerical prefix
    const sortedFiles = sqlFiles.sort((a, b) => {
        // Extract numbers from beginning of filename (must be followed by underscore)
        const matchA = a.match(/^(\d+)_/);
        const matchB = b.match(/^(\d+)_/);

        if (matchA && matchB) {
            // Both have numerical prefixes, sort numerically
            return parseInt(matchA[1], 10) - parseInt(matchB[1], 10);
        } else if (matchA && !matchB) {
            // Only a has prefix, a comes first
            return -1;
        } else if (!matchA && matchB) {
            // Only b has prefix, b comes first
            return 1;
        } else {
            // Neither has prefix, sort alphabetically
            return a.localeCompare(b);
        }
    });

    console.log('Database Migration Files (in order):');
    console.log('====================================\n');

    sortedFiles.forEach((file, index) => {
        console.log(`${index + 1}. ${file}`);
    });

    console.log(`\nTotal: ${sortedFiles.length} migration file(s)`);
}

