/**
 * Simple test server for simulating audit service responses
 */

const http = require('http');

const server = http.createServer((req, res) => {
    console.log(`[${new Date().toISOString()}] Received ${req.method} request to ${req.url}`);

    // Parse body
    let body = '';
    req.on('data', chunk => {
        body += chunk.toString();
    });

    req.on('end', () => {
        try {
            const data = JSON.parse(body);
            console.log('Request body:', JSON.stringify(data, null, 2));

            // Check for CANARY values
            const bodyStr = JSON.stringify(data);
            const canaryFound = bodyStr.includes('CANARY');

            if (req.url === '/api/audit' && req.method === 'POST') {
                if (canaryFound) {
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({
                        status: 'CANARY_DETECTED',
                        message: 'Test canary values detected',
                        found: ['CANARY-db-secret', 'AKIA-CANARY', 'sk-ant-CANARY']
                    }));
                } else {
                    res.writeHead(200, { 'Content-Type': 'application/json' });
                    res.end(JSON.stringify({
                        status: 'OK',
                        message: 'Audit logged successfully'
                    }));
                }
            } else {
                res.writeHead(404, { 'Content-Type': 'text/plain' });
                res.end('Not Found');
            }
        } catch (error) {
            res.writeHead(400, { 'Content-Type': 'text/plain' });
            res.end('Bad Request');
        }
    });
});

const PORT = 47302; // Different port for testing
