#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * 
 * This script reads SQL files from the ./migrations/ directory
 * and logs each filename it would apply, in order.
 */

class MigrationRunner {
    constructor() {
        this.migrationsDir = path.join(__dirname, 'migrations');
        this.migrationFiles = [];
    }

    /**
     * Check if migrations directory exists
     */
    checkMigrationsDir() {
        if (!fs.existsSync(this.migrationsDir)) {
            console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist.`);
            console.info('Please create a ./migrations/ directory with your SQL migration files.');
            process.exit(1);
        }
    }

    /**
     * Get all migration files from the migrations directory
     */
    getMigrationFiles() {
        try {
            const files = fs.readdirSync(this.migrationsDir);

            // Filter for .sql files and sort them
            this.migrationFiles = files
                .filter(file => file.endsWith('.sql'))
                .sort((a, b) => {
                    // Extract numeric prefixes for sorting
                    const numA = this.extractMigrationNumber(a);
                    const numB = this.extractMigrationNumber(b);

                    if (numA !== null && numB !== null) {
                        return numA - numB;
                    }

                    // If no numbers found, sort alphabetically
                    return a.localeCompare(b);
                });

            if (this.migrationFiles.length === 0) {
                console.info('No SQL migration files found in the migrations directory.');
            }

            return this.migrationFiles;
        } catch (error) {
            console.error(`Error reading migrations directory: ${error.message}`);
            process.exit(1);
        }
    }

    /**
     * Extract numeric prefix from migration filename
     * @param {string} filename - The migration filename
     * @returns {number|null} - The extracted number or null
     */
    extractMigrationNumber(filename) {
        const match = filename.match(/^(\d+)_/);
        return match ? parseInt(match[1], 10) : null;
    }

    /**
     * Log migration files in order
     */
    logMigrations() {
        console.log('Database Migration Script');
        console.log('=========================');
        console.log(`Reading migrations from: ${this.migrationsDir}`);
        console.log('');

        if (this.migrationFiles.length === 0) {
            console.log('No migrations to apply.');
            return;
        }

        console.log(`Found ${this.migrationFiles.length} migration(s) to apply:\n`);

        this.migrationFiles.forEach((file, index) => {
            const migrationNum = this.extractMigrationNumber(file);
            const prefix = migrationNum ? `[${String(migrationNum).padStart(3, '0')}]` : '[---]';
            console.log(`${prefix} ${file}`);
        });

        console.log('\nMigrations would be applied in the order shown above.');
    }

    /**
     * Read and display SQL content (optional feature)
     */
    displaySqlContent() {
        console.log('\nSQL Content Preview:');
        console.log('===================');

        this.migrationFiles.forEach((file, index) => {
            const filePath = path.join(this.migrationsDir, file);
            try {
                const content = fs.readFileSync(filePath, 'utf8');
                console.log(`\n--- ${file} ---`);
                console.log(content.substring(0, 200) + (content.length > 200 ? '...' : ''));
            } catch (error) {
                console.error(`Error reading ${file}: ${error.message}`);
            }
        });
    }

    /**
     * Main run method
     */
    run() {
        this.checkMigrationsDir();
        this.getMigrationFiles();
        this.logMigrations();

        // Optional: Show a preview of SQL content
        // Uncomment the line below if you want to see SQL content
        // this.displaySqlContent();
    }
}

// If this script is run directly (not imported as a module)
if (require.main === module) {
    const migrationRunner = new MigrationRunner();
    migrationRunner.run();
}

module.exports = MigrationRunner;

