            // If parsing fails, use the original URL
        }

        console.log(`Connection string: ${loggedUrl}`);
        console.log('✓ Would connect to database successfully');
    } else {
        console.log('⚠ No database connection string available');
        console.log('  Ensure .env.test contains DATABASE_URL for database operations');
    }
}

/**
 * Check if migrations directory exists
 */
checkMigrationsDir() {
    if (!fs.existsSync(this.migrationsDir)) {
        console.error(`Error: Migrations directory '${this.migrationsDir}' does not exist.`);
        console.info('Please create a ./migrations/ directory with your SQL migration files.');
        process.exit(1);
    }
}

